		["{npc:3597}, the druid trainer at {area:256}"] = "{npc:3597}, le maître des druides à {area:256}",
		["{npc:3600}: {npc:11401} in {zone:1457} takes it"] = "{npc:3600} : {npc:11401} à {zone:1457} la prend",
