t.guides["forever/alliance/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "/s'asseoir près du feu de {npc:263664} jusqu'à obtenir {spell:1229451}",
		["Al'Aketh Stormchasers and Footsoldiers camp just north of {npc:257944} and drop the heirloom; the Shrieklings west of her drop the feathers and talons; the {item:265105} grows along the stream west of her."] = "Les Chasse-tempêtes et Fantassins al'aketh campent juste au nord d'{npc:257944} et lâchent l'héritage ; les criailleuses à l'ouest lâchent les plumes et les serres ; {item:265105} pousse le long du ruisseau à l'ouest.",
		["Back in {quest:92529}: Stormcallers and {npc:251662} fill the village, the Stormcallers carry the stolen supplies, and {npc:251966} stands at its south end."] = "De retour à {quest:92529} : des Mande-foudre al'aketh et {npc:251662} emplissent le village, les Mande-foudre portent les provisions volées, et {npc:251966} se tient au sud.",
		["Back to Shen'dar"] = "Retour à Shen'dar",
		["Back to the Hermit"] = "Retour à l'ermite",
		["Back to {area:16622}"] = "Retour à {area:16622}",
		["Back to {npc:255853} by the falls north-east of {area:16638}, on the way north to the shrine."] = "Retournez voir {npc:255853} près des chutes au nord-est de {area:16638}, sur le chemin du sanctuaire au nord.",
		["Bandit Highwaymen"] = "Bandits de grand chemin",
		["Bolvar Fordragon stands in the throne room of {object:2117}, at the north end of the city. Then leave by the main gate for {zone:1436}."] = "Bolvar Fordragon se tient dans la salle du trône de {object:2117}, au nord de la ville. Sortez ensuite par la grande porte vers {zone:1436}.",
		["Cast {spell:1259705} at the {object:460002}"] = "Utilisez votre capacité raciale {spell:1259705} sur la ligne tellurique",
		["Desperate times"] = "Temps désespérés",
		["Each of Quel'ana's quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her in {area:16638}. Windsong Crawlers line the shore west of town; Vuldren Alphas and Ornery Galestriders roam the {area:16626} around the Windfield farm. Her sister {npc:254411} stands beside her."] = "Chaque quête de Quel'ana vous remet un {item:15908} : utilisez-le sur la bête qu'elle désigne, puis rapportez-le-lui à {area:16638}. Les Clampants chantevent bordent le rivage à l'ouest de la ville ; les Alphas vuldrènes et les Trotteurs des trombes hargneux errent dans {area:16626} autour de la ferme Windfield. Sa sœur {npc:254411} se tient à côté d'elle.",
		["Fight north to the {area:16629}. Guardians, Spiritcallers and Blademasters hold the approach; {npc:253576} waits at the shrine's door, {npc:253590} inside the inner sanctum."] = "Frayez-vous un chemin vers le nord jusqu'à {area:16629}. Des Gardiens, Mande-esprit et Maîtres-lames al'aketh tiennent l'accès ; {npc:253576} attend à la porte du sanctuaire, {npc:253590} dans le sanctum intérieur.",
		["Find Fillion and his bedroll"] = "Trouver Fillion et son sac de couchage",
		["Follow the road south to {area:16624}. {npc:263664} camps by the fire west of the village; {npc:251523} and {npc:251903} stand in its middle."] = "Suivez la route vers le sud jusqu'à {area:16624}. {npc:263664} campe près du feu à l'ouest du village ; {npc:251523} et {npc:251903} se tiennent au centre.",
		["For {npc:234} at {area:108}"] = "Pour {npc:234} à {area:108}",
		["Havoc in Falaath"] = "Chaos à Falaath",
		["Head north into {area:16631}. {npc:257944} camps in its east."] = "Allez au nord dans {area:16631}. {npc:257944} campe dans sa partie est.",
		["Head north-west to the hippogryph nests on the western cliffs. {item:263493} lies around the nests; the Matriarch patrols among them."] = "Allez au nord-ouest jusqu'aux nids d'hippogriffes sur les falaises ouest. {item:263493} se trouve autour des nids ; la Matriarche hippogriffe patrouille parmi eux.",
		["Heal 7 druids in the Nightfang Den, then find {npc:258130}"] = "Soigner 7 druides dans la tanière, puis trouver {npc:258130}",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Quittez {zone:1453} par la grande porte. La cascade de {quest:1861} est au sud-ouest des portes, sur la route de {zone:1436} à l'ouest : remplissez {item:7207} à son pied.",
		["Level 4 spells"] = "Sorts de niveau 4",
		["Level 6 spells"] = "Sorts de niveau 6",
		["Listen to {npc:257554}"] = "Écouter {npc:257554}",
		["Lorthuna waits on the eastern shore of the isle, east of the {area:16629}."] = "Lorthuna attend sur la rive est de l'île, à l'est de {area:16629}.",
		["Meet Valennia at the gate"] = "Rejoindre Valennia à la porte",
		["North of the cones: the Wind Hollows drift around the refugees' camp, the {item:266433} lie between the tents, and {npc:259013} lies at its north end."] = "Au nord des cônes : les Creux du vent dérivent autour du camp des réfugiés, {item:266433} sont entre les tentes, et {npc:259013} gît au nord du camp.",
		["North-west of Valanaar along the road: {npc:273017} watches the {quest:98512}; the dead cultist lies just north of him."] = "Au nord-ouest de Valanaar, le long de la route : {npc:273017} surveille {quest:98512} ; le cultiste mort gît juste au nord.",
		["Prideclaws and Galestriders"] = "Fièregriffes et trotteurs des trombes",
		["Prideclaws and Galestriders roam the grasslands south of the village. Galestriders drop both the eggs and the meat."] = "Les Fièregriffes et les Trotteurs des trombes errent dans les prairies au sud du village. Les Trotteurs des trombes lâchent les œufs et la viande.",
		["Rally Valennia, {npc:251968} (west of town) and {npc:252475}"] = "Rallier Valennia, {npc:251968} (à l'ouest de la ville) et {npc:252475}",
		["Raw Windstones and the {npc:251404}"] = "Pierres de vent brutes et {npc:251404}",
		["Ripe Stormapples and Hungry Bandits are in the orchard by the farm, {quest:92683} in the fields north-east of it, Ornery Galestriders all around. The {npc:250929} stands in the field north-east of the farm."] = "Les Pommes d’orage mûres et les Bandits affamés sont dans le verger près de la ferme, {quest:92683} dans les champs au nord-est, et les Trotteurs des trombes hargneux tout autour. {npc:250929} se tient dans le champ au nord-est de la ferme.",
		["Search the dead cultist"] = "Fouiller le cultiste mort",
		["Search the wardrobe"] = "Fouiller l'armoire",
		["Shen'dar turn-ins"] = "Quêtes à rendre à Shen'dar",
		["Skycutter to {area:279}"] = "Fend-ciel pour {area:279}",
		["Skyhoppers"] = "Sauteciels",
		["Skyhoppers swarm the fields west of {area:16638}."] = "Les Sauteciels pullulent dans les champs à l'ouest de {area:16638}.",
		["Speak with {npc:251903} and {npc:254089}, north-west of the village"] = "Parler à {npc:251903} et {npc:254089}, au nord-ouest du village",
		["Stand with {npc:252800} against {npc:252863}"] = "Combattre {npc:252863} aux côtés d'{npc:252800}",
		["Standing our ground"] = "Tenir bon",
		["Take the road south-east. {npc:257006} and {npc:252448} stand by the road west of {area:16638}; Windsong Crawlers line the shore further west, around 51,70."] = "Prenez la route vers le sud-est. {npc:257006} et {npc:252448} se tiennent au bord de la route à l'ouest de {area:16638} ; des Clampants chantevent bordent le rivage plus à l'ouest, vers 51,70.",
		["Tame it with the {item:15908}"] = "L'apprivoiser avec le {item:15908}",
		["The Bandit Highwaymen hold the hills north of the farm."] = "Les Bandits de grand chemin tiennent les collines au nord de la ferme.",
		["The Highlands Bandits camp north-east of the village. \"Badwind\" Bennic waits at the far north end of their camp."] = "Les Bandits des hautes-terres campent au nord-est du village. Bennic « Mauvais vent » attend tout au nord de leur camp.",
		["The Highlands bandits"] = "Les bandits des hautes-terres",
		["The Novice Seers practise in the clearing west of Shen'dar."] = "Les Voyants novices s'entraînent dans la clairière à l'ouest de Shen'dar.",
		["The Raw Windstones glitter on the ground just south of the grove. {quest:92463} hovers over the meadow further east, on the way to {npc:249363}."] = "Les Pierres de vent brutes scintillent au sol juste au sud du bosquet. {quest:92463} plane au-dessus de la prairie plus à l'est, sur le chemin de {npc:249363}.",
		["The Windfield farm"] = "La ferme Windfield",
		["The Windstone Formations"] = "Les Formations de pierre des vents",
		["The Windstone Formations stand on the rise west of Fillion's camp."] = "Les Formations de pierre des vents se dressent sur la butte à l'ouest du camp de Fillion.",
		["The bounty board"] = "Le tableau des primes",
		["The class trainers stand together in the grove"] = "Les maîtres de classe se tiennent ensemble dans le bosquet",
		["The dead cultist"] = "Le cultiste mort",
		["The eastern watchtower"] = "La tour de guet est",
		["The hippogryph roost"] = "Le perchoir des hippogriffes",
		["The missing scholar"] = "L’érudit disparu",
		["The refugees' camp"] = "Le camp des réfugiés",
		["The road to {area:16638}"] = "La route de {area:16638}",
		["The skycutter"] = "Le fend-ciel",
		["The skycutter docks at the tower south of {area:16638}. It lands by the Kirin Tor camp on the lake shore west of {area:279}."] = "Le fend-ciel accoste à la tour au sud de {area:16638}. Il se pose près du camp du Kirin Tor sur la rive du lac, à l'ouest de {area:279}.",
		["The {area:16629}"] = "{area:16629}",
		["The {item:254871}"] = "{item:254871}",
		["The {object:581822}"] = "{object:581822}",
		["The {object:581822} lies by the path west of {area:16638}; Fillion's camp is north-west of it, and the Shriekling Matriarchs nest just west of the camp."] = "{object:581822} est au bord du chemin à l'ouest de {area:16638} ; le camp de Fillion est au nord-ouest, et les Matriarches criailleuses nichent juste à l'ouest du camp.",
		["Use {spell:1259416}"] = "Utilisez {spell:1259416}",
		["Village quests"] = "Quêtes du village",
		["Vuldren and Cirrusflies"] = "Vuldrènes et mouches-cirrus",
		["Windshaper Novice Seers"] = "Voyants novices des Sculpte-vents",
		["You wake in {area:16622}. {npc:251362} stands beside you; {npc:251361} is a few steps west, {npc:251368} by the south edge of the grove."] = "Vous vous réveillez à {area:16622}. {npc:251362} est à côté de vous ; {npc:251361} est à quelques pas à l'ouest, {npc:251368} près de la lisière sud du bosquet.",
		["{area:16622} turn-ins"] = "Quêtes à rendre à {area:16622}",
		["{area:16624} again"] = "De nouveau {area:16624}",
		["{area:16638} turn-ins"] = "Quêtes à rendre à {area:16638}",
		["{area:16638}, the fate of Zephras"] = "{area:16638}, le destin de Zephras",
		["{area:16638}, the turncoat"] = "{area:16638}, le traître",
		["{item:262668}: by the wind shrine south of {quest:92529}"] = "{item:262668} : près du sanctuaire du vent au sud de {quest:92529}",
		["{item:263993}: {npc:257196}, west of the shrine's approach"] = "{item:263993} : {npc:257196}, à l'ouest de l'accès au sanctuaire",
		["{npc:249363} keeps watch east of the grove. The {npc:251143} and Al'Aketh Converts gather just north of her; the {object:460002} rises further north: cast your {spell:1259705} racial ability at it."] = "{npc:249363} monte la garde à l'est du bosquet. {npc:251143} et des Convertis al'aketh ({npc:251160}) se rassemblent juste au nord d'elle ; la ligne tellurique s'élève plus au nord : utilisez-y votre capacité raciale {spell:1259705}.",
		["{npc:250873} and Pesky Cirrusflies roam the meadow just south-east of the grove."] = "{npc:250873} et Mouches-cirrus agaçantes errent dans la prairie juste au sud-est du bosquet.",
		["{npc:250926} and {npc:251115}"] = "{npc:250926} et {npc:251115}",
		["{npc:250926} prowl the woods just west of the grove; the Ursera Scavengers den further west, with {npc:251115}, the matriarch, at the back of the den."] = "{npc:250926} rôdent dans les bois juste à l'ouest du bosquet ; les Charognards ursera ont leur tanière plus à l'ouest, avec {npc:251115}, la matriarche, au fond.",
		["{npc:251361}: a note from your trainer"] = "{npc:251361} : un mot de votre maître",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361} : lisez {item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361} : {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}, le maître des druides, au rez-de-chaussée de l'arbre derrière {npc:251361}",
		["{npc:251379}, the mage trainer: read the {item:282416} first"] = "{npc:251379}, le maître des mages : lisez d'abord {item:282416}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}, dans la tour de guet",
		["{npc:251964}, in the watchtower"] = "{npc:251964}, dans la tour de guet",
		["{npc:252095} camps south of the Ursera den. The Al'Aketh thugs hold the camp south-west of her; {npc:256935} stands in its middle."] = "{npc:252095} campe au sud de la tanière des ursera. Les voyous al'aketh tiennent le camp au sud-ouest ; {npc:256935} se tient en son centre.",
		["{npc:252155} holds the western watch, south-west of Falaath. {npc:256966} and the fallen guards lie just south of her."] = "{npc:252155} tient le poste de guet ouest, au sud-ouest de Falaath. {npc:256966} et les gardes tombés gisent juste au sud.",
		["{npc:252373}, the mage trainer"] = "{npc:252373}, le maître des mages",
		["{npc:252377}: {npc:257196} waits at the {area:16629}"] = "{npc:252377} : {npc:257196} attend à {area:16629}",
		["{npc:252378} holds the watchtower north of {area:16638}. The Al'Aketh camp is just west of the tower, its healers around 65,68 and 65,65; {npc:252666} stands at its north end. The Al'Aketh there drop Windstone Charms."] = "{npc:252378} tient la tour de guet au nord de {area:16638}. Le camp al'aketh est juste à l'ouest de la tour, ses soigneurs vers 65,68 et 65,65 ; {npc:252666} se tient au nord du camp. Les Al'aketh y lâchent des Charmes de pierre de vent al’aketh.",
		["{npc:252383} and {npc:252476} stand at the north end of {area:16638}, {npc:252475} and {npc:253204} at the south end."] = "{npc:252383} et {npc:252476} se tiennent au nord de {area:16638}, {npc:252475} et {npc:253204} au sud.",
		["{npc:252475}: {npc:259084} waits by the Skyborne portal"] = "{npc:252475} : {npc:259084} attend près du portail éolide",
		["{npc:252800} again"] = "De nouveau {npc:252800}",
		["{npc:252800} runs the farm in the south-west lowlands."] = "{npc:252800} tient la ferme dans les basses terres du sud-ouest.",
		["{npc:253590}, in the sanctum"] = "{npc:253590}, dans le sanctum",
		["{npc:254151}, {npc:258130} and {npc:258134} are north-east of {npc:257944}; {npc:253622} stands east of them. Haalien also drops a {quest:94490}."] = "{npc:254151}, {npc:258130} et {npc:258134} sont au nord-est d'{npc:257944} ; {npc:253622} se tient à l'est d'eux. Haalien lâche aussi {quest:94490}.",
		["{npc:254588}: tame it with the {item:15908}"] = "{npc:254588} : apprivoisez-le avec le {item:15908}",
		["{npc:254589} lurks in the hills south-west of the village, on the way back. {npc:254589} is elite: grouping up is advised."] = "{npc:254589} rôde dans les collines au sud-ouest du village, sur le chemin du retour. {npc:254589} est un élite : mieux vaut être en groupe.",
		["{npc:255853} waits by the falls north-east of {area:16638}. {npc:258443} prowls the {area:16623} west of {area:16638}, by the road you take next."] = "{npc:255853} attend près des chutes au nord-est de {area:16638}. {npc:258443} rôde dans {area:16623} à l'ouest de {area:16638}, près de la route que vous prendrez ensuite.",
		["{npc:257065} waits at the entrance to {quest:92529}, south of Shen'dar. The {spell:1254832} lets you walk in among the faithful."] = "{npc:257065} attend à l'entrée de {quest:92529}, au sud de Shen’dar. {spell:1254832} vous permet d'entrer parmi les fidèles.",
		["{npc:257944} again"] = "De nouveau {npc:257944}",
		["{npc:257944}, the missive"] = "{npc:257944}, la missive",
		["{npc:258443}, in the highlands south-west of the cultist"] = "{npc:258443}, dans les hautes-terres au sud-ouest du cultiste",
		["{npc:259084} stands beside the Skyborne Portal where the zeppelin lands. The portal takes you to {zone:1453}."] = "{npc:259084} se tient près du portail éolide, là où le zeppelin se pose. Le portail vous mène à {zone:1453}.",
		["{npc:270459}, beside {npc:259084}: for {npc:5504} in {zone:1453}"] = "{npc:270459}, à côté de {npc:259084} : pour {npc:5504} à {zone:1453}",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497} se tient dans la tour de {object:2101} ; elle vous donne une flasque pour la cascade de {quest:1861}.",
		["{npc:5504}, {zone:1453}'s druid trainer, teaches you {spell:18960}. {npc:11802}'s welcome waits for your {spell:499} trip at the end of {zone:1439}."] = "{npc:5504}, le maître des druides de {zone:1453}, vous enseigne {spell:18960}. L'accueil de {npc:11802} attend votre voyage en {spell:499} à la fin de {zone:1439}.",
		["{quest:93159} lives west of {npc:257944}. The Zephyrseed Cones lie in the woods between his hut and {npc:257944}."] = "{quest:93159} vit à l'ouest d'{npc:257944}. Les Cônes de graine-de-zéphyr ({object:613238}) se trouvent dans les bois entre sa cabane et {npc:257944}.",
} end)()
t.guides["forever/class/druid/aquatic-form"] = (function() return {
		["At the {area:2362}"] = "Au {area:2362}",
		["Cast {spell:18960}. Join the two halves into the {item:15885} near the {area:2362}, on the north-west shore of the lake, then see {npc:11802} in {area:2361}. Fly to {area:702} afterwards."] = "Lancez {spell:18960}. Assemblez les deux moitiés pour obtenir {item:15885} près du {area:2362}, sur la rive nord-ouest du lac, puis allez voir {npc:11802} à {area:2361}. Volez ensuite jusqu'à {area:702}.",
		["Cast {spell:18960}. Join the two halves into the {item:15885} near the {area:2362}, on the north-west shore of the lake, then see {npc:11802} in {area:2361}. {npc:11798} flies druids to {area:1638}."] = "Lancez {spell:18960}. Assemblez les deux moitiés pour obtenir {item:15885} près du {area:2362}, sur la rive nord-ouest du lac, puis allez voir {npc:11802} à {area:2361}. {npc:11798} transporte les druides jusqu'à {area:1638}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Shrine Baubles lie in the containers on the floor of {area:656}, below {area:2361}: take one to the {area:2362} on the north-west shore, use it there and speak to {npc:11799}."] = "Lancez {spell:18960}. {npc:11802} est à {area:2361}. Les Colifichets du sanctuaire ({item:15877}) se trouvent dans les conteneurs au fond du {area:656}, en contrebas de {area:2361} : apportez-en un au {area:2362} sur la rive nord-ouest, utilisez-le là-bas et parlez à {npc:11799}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. The Shrine Baubles lie on the bed of {area:656} and fade within minutes: swim one straight to the {area:2362} on the north-west shore, use it there and speak to {npc:11799}."] = "Lancez {spell:18960}. {npc:11802} est à {area:2361}. Les Colifichets du sanctuaire ({item:15877}) reposent au fond du {area:656} et disparaissent en quelques minutes : nagez avec l'un d'eux directement jusqu'au {area:2362} sur la rive nord-ouest, utilisez-le là-bas et parlez à {npc:11799}.",
		["Fly from {area:2361} to {area:442}. The {object:177792} lies under the water off the north coast, west of the {area:443}."] = "Volez de {area:2361} à {area:442}. L'{object:177792} se trouve sous l'eau au large de la côte nord, à l'ouest des {area:443}.",
		["Take the boat from {area:442} to {zone:1453} and fly to {area:108}. Ride north-west to the coast: the {object:177790} lies on the sea floor off the shore."] = "Prenez le bateau d'{area:442} à {zone:1453} et volez jusqu'à la {area:108}. Allez vers le nord-ouest jusqu'à la côte : l'{object:177790} repose sur le fond marin au large du rivage.",
		["Take the portal up to {npc:4217} in the {area:1658}."] = "Prenez le portail qui monte jusqu'à {npc:4217}, dans l'{area:1658}.",
		["Take {npc:11798}'s flight to {zone:1456}, fly to {zone:1454} and take the zeppelin to {zone:1420}; {zone:1421} is south of the {zone:1458}. The {object:177790} lies on the coast west of the {area:240}, north of the {area:228}."] = "Prenez le vol de {npc:11798} jusqu'à {zone:1456}, volez jusqu'à {zone:1454} et prenez le zeppelin pour {zone:1420} ; {zone:1421} se trouve au sud d'{zone:1458}. L'{object:177790} se trouve sur la côte à l'ouest du champ ({area:240}), au nord de la crypte ({area:228}).",
		["The {object:177792} lies at the north edge of the {area:382}, by the Venture Co. tower, north of the {area:380}."] = "L'{object:177792} se trouve à la lisière nord de {area:382}, près de la tour de la KapitalRisk, au nord de {area:380}.",
		["Your water travel form: swim fast and breathe underwater, with a belt and an idol besides."] = "Votre forme de voyage aquatique : nagez vite et respirez sous l'eau, avec en plus une ceinture et une idole.",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, dans un {object:177785} au fond du lac",
		["{item:15885}: join the halves at the shrine"] = "{item:15885} : assemblez les moitiés au sanctuaire",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033} se tient sur la {area:1639}.",
		["{npc:4217} stands in the {area:1658}."] = "{npc:4217} se tient dans l'{area:1658}.",
} end)()
t.guides["forever/class/druid/bear-form"] = (function() return {
		["At 10 a druid's call reaches you: {npc:3064} in {area:222} or {npc:6746} in {zone:1456} ({npc:6929}'s letter in {zone:1454} works too). Any one of them sends you to {npc:3033} on {area:1639} in {zone:1456}."] = "Au niveau 10, l'appel d'un druide vous parvient : {npc:3064} à {area:222} ou {npc:6746} à {zone:1456} (la lettre de {npc:6929} à {zone:1454} fonctionne aussi). N'importe lequel vous envoie voir {npc:3033} sur {area:1639}, à {zone:1456}.",
		["At 10 a druid's call reaches you: {npc:3602} in {area:186}, Denatharion in {zone:1457} or Theridran in {zone:1453}. Any one of them sends you to {npc:4217} in the Cenarion Enclave of Darnassus."] = "Au niveau 10, l'appel d'un druide vous parvient : {npc:3602} à {area:186}, Denatharion à {zone:1457} ou Theridran à {zone:1453}. N'importe lequel vous envoie voir {npc:4217} à l'Enclave cénarienne de Darnassus.",
		["Back to {npc:255853} by the falls."] = "Retournez voir {npc:255853} près des chutes.",
		["Back to {npc:3033} on {area:1639}."] = "Retournez voir {npc:3033} sur {area:1639}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Learn the {area:493} flight path while you are here."] = "Lancez {spell:18960}. {npc:11802} est à {area:2361}. Apprenez le trajet aérien de {area:493} pendant que vous y êtes.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Learn the {area:493} flight path, then fly to {area:702} (by way of {area:442}) and take the portal up to {zone:1457}."] = "Lancez {spell:18960}. {npc:11802} est à {area:2361} ; {quest:5929} se trouve dans les bois au nord-ouest. Apprenez le trajet aérien de {area:493}, puis volez jusqu'à {area:702} (en passant par {area:442}) et prenez le portail pour monter à {zone:1457}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5930} sits in the woods to the north-west. {npc:11798} in {area:2361} flies druids to {area:1638}."] = "Lancez {spell:18960}. {npc:11802} est à {area:2361} ; {quest:5930} se trouve dans les bois au nord-ouest. {npc:11798}, à {area:2361}, transporte les druides jusqu'à {area:1638}.",
		["Fly back to {area:702} and take the portal up to {npc:4217}."] = "Retournez en vol à {area:702} et prenez le portail pour rejoindre {npc:4217}.",
		["Fly from {area:702} to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "Volez de {area:702} à {area:442}. {object:177525} se dresse dans les collines juste à l'est du village : utilisez-y {item:15208}, vainquez Lunegriffe et parlez à {npc:12144}.",
		["Skyboat from {area:279}"] = "Aéronef depuis {area:279}",
		["Skyboat from {zone:1456}"] = "Aéronef depuis {zone:1456}",
		["Skyboat to {zone:2521}"] = "Aéronef vers {zone:2521}",
		["Speak with the {quest:5929}"] = "Parler à {quest:5929}",
		["Speak with the {quest:5930}"] = "Parler à {quest:5930}",
		["The Skyborne Portal takes you to {zone:1453}. {npc:5504} is the city's druid trainer."] = "Le portail éolide vous mène à {zone:1453}. {npc:5504} est le maître des druides de la ville.",
		["The {object:177525}"] = "{object:177525}",
		["The {object:177525} stands in the pass from {zone:1412} into the {zone:1413}. Use the {item:15710} there, defeat Lunaclaw and speak to the {npc:12144}."] = "{object:177525} se dresse dans le col entre {zone:1412} et {zone:1413}. Utilisez-y {item:15710}, vainquez Lunegriffe et parlez à {npc:12144}.",
		["Your tanking form: Forever no longer trains {spell:5487}, these quests give it. Opens {area:493} too."] = "Votre forme de tank : Forever n'enseigne plus {spell:5487}, ces quêtes la donnent. Elles ouvrent aussi {area:493}.",
		["or whichever of the three letters you carry"] = "ou celle des trois lettres que vous portez",
		["{npc:252359} stands in {area:16638}."] = "{npc:252359} se tient à {area:16638}.",
		["{npc:255853} and {npc:258443}"] = "{npc:255853} et {npc:258443}",
		["{npc:255853} waits by the falls north-east of {area:16638}. {npc:258443} prowls the {area:16623}, west of {area:16638}."] = "{npc:255853} attend près des chutes au nord-est de {area:16638}. {npc:258443} rôde dans {area:16623}, à l'ouest de {area:16638}.",
		["{npc:259118} waits where the airship from {zone:2521} lands, in northern {zone:1412} beside {zone:1456}."] = "{npc:259118} attend là où se pose l'aéronef venu de {zone:2521}, au nord de {zone:1412}, près de {zone:1456}.",
		["{npc:270459} stands beside {npc:259084} and the Skyborne Portal, west of {area:279}, where the skycutter from {zone:2521} lands. {npc:2543} offers the same quest."] = "{npc:270459} se tient à côté de {npc:259084} et du portail éolide, à l'ouest de {area:279}, là où se pose le fend-ciel venu de {zone:2521}. {npc:2543} propose la même quête.",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033} se tient sur {area:1639}.",
		["{npc:3033} trains druids on {area:1639}."] = "{npc:3033} forme les druides sur {area:1639}.",
		["{npc:3064}, {area:222}; Pala's and Gryshka's letters lead to the same place"] = "{npc:3064}, {area:222} ; les lettres de Pala et de Gryshka mènent au même endroit",
		["{npc:3602}, {area:186}; Denatharion's and Theridran's letters lead to the same place"] = "{npc:3602}, {area:186} ; les lettres de Denatharion et de Theridran mènent au même endroit",
		["{npc:4217} stands in the {area:1658}."] = "{npc:4217} se tient dans {area:1658}.",
		["{spell:5487} and {area:493}"] = "{spell:5487} et {area:493}",
		["{spell:5487} is taught on {zone:2521}. Skip this if you are still on the isle; otherwise take the skyboat from the cliffs south of {area:17045}, north of {zone:1456}."] = "{spell:5487} s'apprend sur {zone:2521}. Passez cette étape si vous êtes encore sur l'île ; sinon, prenez l'aéronef depuis les falaises au sud de {area:17045}, au nord de {zone:1456}.",
		["{spell:5487} is taught on {zone:2521}. Skip this if you are still on the isle; otherwise take the skyboat from the north side of {area:279}."] = "{spell:5487} s'apprend sur {zone:2521}. Passez cette étape si vous êtes encore sur l'île ; sinon, prenez l'aéronef au nord de {area:279}.",
} end)()
t.guides["forever/class/druid/bloodpetal-poison"] = (function() return {
		["Back to {npc:9619} in the south-east corner of {zone:1449}."] = "Retournez voir {npc:9619} dans le coin sud-est de {zone:1449}.",
		["Cast {spell:18960}. {npc:12042} stands in {area:2361}; your class trainer offers the same quest."] = "Lancez {spell:18960}. {npc:12042} se tient à {area:2361} ; votre maître de classe propose la même quête.",
		["Experience in Un'Goro at 50 and two healing potions; Forever removed the Classic item choice."] = "De l'expérience à Un'Goro au niveau 50 et deux potions de soins ; Forever a retiré le choix d'objet de Classic.",
		["Fly to {area:976}, ride west to the long ramp down into {zone:1449}: {npc:9619} camps at its foot, in the south-east corner of the crater."] = "Prenez un vol pour {area:976}, puis allez à l'ouest jusqu'à la longue rampe qui descend dans {zone:1449} : {npc:9619} campe à son pied, dans le coin sud-est du cratère.",
		["Gorishi Stings and {item:22434}"] = "Dards de Gorishi et {item:22434}",
		["The Gorishi wasps, workers and reavers of the hive in the south of the crater drop the stings; the Bloodpetal Sprouts that give the {item:22434} grow all over the crater's western half."] = "Les Guêpes, Ouvriers et Ravageurs Gorishi de la ruche au sud du cratère laissent tomber les dards ; les Pousses de Pétale-de-sang qui donnent le {item:22434} poussent dans toute la moitié ouest du cratère.",
		["The {area:1417}"] = "{area:1417}",
		["Use the {item:22432} on a {npc:6498}. Devilsaurs are elite (level 54-55) and roam the crater: grouping up is advised."] = "Utilisez l'{item:22432} sur un {npc:6498}. Les Diablosaures sont élites (niveau 54-55) et parcourent le cratère : un groupe est conseillé.",
		["{area:1477} lies in the {area:74} in the {zone:1435}. {npc:8580} guards the bottom of the temple: a dungeon boss, so bring a group."] = "{area:1477} se trouve dans {area:74}, dans {zone:1435}. {npc:8580} garde le fond du temple : c'est un boss de donjon, venez en groupe.",
		["{npc:6498}: stab it with the {item:22432}"] = "{npc:6498} : piquez-le avec l'{item:22432}",
} end)()
t.guides["forever/class/druid/cat-form"] = (function() return {
		["Back to {npc:11802}"] = "Retour auprès de {npc:11802}",
		["Back to {npc:11802} in {area:2361}, then fly to {area:702}."] = "Retournez voir {npc:11802} à {area:2361}, puis prenez un vol pour {area:702}.",
		["Back to {npc:11802} in {area:2361}, then take {npc:11798}'s flight to {area:1638}."] = "Retournez voir {npc:11802} à {area:2361}, puis prenez le vol de {npc:11798} pour {area:1638}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}."] = "Lancez {spell:18960}. {npc:11802} est à {area:2361}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; learn the flight path there if you do not have it."] = "Lancez {spell:18960}. {npc:11802} est à {area:2361} ; apprenez-y le trajet aérien si vous ne l'avez pas.",
		["Take the portal up to {npc:4217} in the {area:1658}."] = "Prenez le portail pour monter voir {npc:4217} dans {area:1658}.",
		["The relics of the Barrow Dens"] = "Les reliques du Refuge des saisons",
		["The {area:2363}"] = "{area:2363}",
		["Your stealth and melee form: in Forever this chain gives {spell:768} at 20, not the trainer."] = "Votre forme de camouflage et de mêlée : dans Forever, cette suite de quêtes donne {spell:768} au niveau 20, pas le maître.",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033} se trouve sur {area:1639}.",
		["{npc:4217} stands in the {area:1658}. Skyborne without the Rut'theran flight path: take the boat from {area:442}."] = "{npc:4217} se trouve dans {area:1658}. Éolides sans le trajet aérien de Rut'theran : prenez le bateau depuis {area:442}.",
		["{quest:98342} (Tauren) waits on the southern hill above the bridge, the {npc:272054} (Skyborne) south of the twin bridges. The relics lie in the {area:2363} east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue. A relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98342} (Taurens) attend sur la colline sud au-dessus du pont, l'{npc:272054} (Éolides) au sud des ponts jumeaux. Les reliques se trouvent dans {area:2363}, à l'est du lac : quittez votre forme, cliquez sur la statue de l'entrée pour cinq minutes de camouflage, évitez les esprits à l'intérieur et prenez une relique de chaque ; la {item:280680} se trouve au pied de la statue de félin blanc. Une relique ne donne rien pendant qu'un autre joueur la fouille : patientez un instant et réessayez.",
		["{quest:98394} (Night Elves) waits on the southern hill above the bridge, the {npc:272054} (Skyborne) south of the twin bridges. The relics lie in the {area:2363} east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue. A relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394} (Elfes de la nuit) attend sur la colline sud au-dessus du pont, l'{npc:272054} (Éolides) au sud des ponts jumeaux. Les reliques se trouvent dans {area:2363}, à l'est du lac : quittez votre forme, cliquez sur la statue de l'entrée pour cinq minutes de camouflage, évitez les esprits à l'intérieur et prenez une relique de chaque ; la {item:280680} se trouve au pied de la statue de félin blanc. Une relique ne donne rien pendant qu'un autre joueur la fouille : patientez un instant et réessayez.",
} end)()
t.guides["forever/class/druid/cure-poison"] = (function() return {
		["Back in {area:442}."] = "De retour à {area:442}.",
		["Cast {spell:18960} and see {npc:11802}, then fly to {area:702} and take the portal up to {zone:1457}."] = "Lancez {spell:18960} et allez voir {npc:11802}, puis volez jusqu'à {area:702} et prenez le portail pour monter à {zone:1457}.",
		["Cast {spell:18960} and see {npc:11802}, then take {npc:11798}'s flight to {area:1638}."] = "Lancez {spell:18960} et allez voir {npc:11802}, puis prenez le vol de {npc:11798} jusqu'à {area:1638}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Then fly to {area:442}."] = "Lancez {spell:18960}. {npc:11802} est à {area:2361}. Volez ensuite jusqu'à {area:442}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. {npc:11798} flies druids to {area:1638}; fly on to the {area:380} from there."] = "Lancez {spell:18960}. {npc:11802} est à {area:2361}. {npc:11798} transporte les druides jusqu'à {area:1638} ; de là, volez jusqu'à {area:380}.",
		["From the {area:380} ride north to {area:384} and fill the {item:15842} at the {object:19464}."] = "Depuis {area:380}, chevauchez vers le nord jusqu'à {area:384} et remplissez l'{item:15842} au {object:19464}.",
		["Lost Barrens Kodos roam the plains north and west of the {area:380} and around the {area:388}; each drops a horn. Herbalists find {item:2449} all over the northern {zone:1413}."] = "Des Kodos égarés des Tarides ({npc:3234}) errent dans les plaines au nord et à l'ouest de {area:380} et autour de {area:388} ; chacun lâche une corne. Les herboristes trouvent {item:2449} partout dans le nord de {zone:1413}.",
		["Ride north-east from {area:442} to {area:445} and fill the {item:15844} at the mouth of the cave by the falls."] = "Chevauchez vers le nord-est depuis {area:442} jusqu'à {area:445} et remplissez l'{item:15844} à l'entrée de la grotte près des chutes.",
		["Sickly Gazelles"] = "Gazelles malades",
		["The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of {area:442}; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else buys it from {npc:1313} (Alchemy Supplies) in {zone:1453} or on the Auction House."] = "Les Floraisons fongiques lunaires ({object:177750}) poussent dans les grottes des séléniens dans les collines juste à l'est d'{area:442} ; les séléniens y sont irritables. {item:2449} requiert {skill:182} : les herboristes la cueillent partout à {zone:1439}, les autres l'achètent à {npc:1313} (Fournitures d'alchimie) à {zone:1453} ou à l'hôtel des ventes.",
		["Use the {item:15826} on Sickly Gazelles: they graze north of the road that runs east and west through the {area:380}."] = "Utilisez le {item:15826} sur les Gazelles malades : elles paissent au nord de la route qui traverse {area:380} d'est en ouest.",
		["Use the {item:15826} on {npc:12298}. They roam {zone:1439} from the {area:456} in the north to the {zone:1440} border in the south."] = "Utilisez le {item:15826} sur les {npc:12298}. Ils parcourent {zone:1439}, de {area:456} au nord jusqu'à la frontière d'{zone:1440} au sud.",
		["{item:15851} and {item:2449}"] = "{item:15851} et {item:2449}",
		["{item:2449} and Kodo Horns"] = "{item:2449} et Cornes de kodo",
		["{item:2449}; herbalists pick it on the plains"] = "{item:2449} ; les herboristes en cueillent dans les plaines",
		["{npc:12296}: use the salve on them"] = "{npc:12296} : utilisez le baume sur elles",
		["{npc:12298}: use the salve on them"] = "{npc:12298} : utilisez le baume sur eux",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033} se trouve sur {area:1639}.",
		["{npc:3448} stands in the {area:380}. No {skill:182}? {npc:3490}, a few steps away, sells {item:2449}, three at a time until he restocks."] = "{npc:3448} se trouve à {area:380}. Pas d'{skill:182} ? {npc:3490}, à quelques pas, vend de la {item:2449}, trois à la fois jusqu'à son réapprovisionnement.",
		["{npc:4217} stands in the {area:1658}."] = "{npc:4217} se trouve dans {area:1658}.",
		["{spell:8946} is no longer trained in Forever: this chain teaches it, with a medicine bag on the way."] = "{spell:8946} ne s'apprend plus auprès du maître dans Forever : cette suite de quêtes l'enseigne, avec une sacoche de remèdes en chemin.",
} end)()
t.guides["forever/class/hunter/rhokdelar"] = (function() return {
		["Back to the Ancients"] = "Retour aux Anciens",
		["Hastat's quiver needs the {item:18704}. {npc:6109}, a world boss for a raid, roams the south of {zone:1447} and drops it most of the time; the Cobalt dragonkin of {zone:1452} drop it very rarely. Skip the rest of this guide if you do not want the quiver."] = "Le carquois de Hastat exige le {item:18704}. {npc:6109}, un boss mondial pour un raid, rôde au sud d'{zone:1447} et le lâche la plupart du temps ; les draconiens cobalt du {zone:1452} le lâchent très rarement. Passez le reste de ce guide si vous ne voulez pas le carquois.",
		["Not confirmed in Forever. In Classic, using the {item:18707} with the {item:18724} in your bags made Rhok'delar, and Vartrus then gave {item:18715} ({spell:425121})."] = "Non confirmé dans Forever. Dans Classic, utiliser {item:18707} avec {item:18724} dans vos sacs créait Rhok'delar, arc long des Gardiens anciens, et l'Ancien Vartrus donnait ensuite {item:18715} ({spell:425121}).",
		["Onyxia"] = "Onyxia",
		["Onyxia drops the {item:18705}; she is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}."] = "Onyxia lâche le {item:18705} ; c'est le boss de raid à 40 joueurs de {area:2159}, une grotte dans {area:511}, au sud du {zone:1445}.",
		["Rhok'delar and Lok'delar"] = "Rhok'delar et Lok'delar",
		["The hunter's epic bow chain: in Classic the stave and sinew became Rhok'delar and Lok'delar (unconfirmed in Forever)."] = "La suite de quêtes de l'arc épique des chasseurs : dans Classic, le bâton et le tendon devenaient Rhok'delar et Lok'delar (non confirmé dans Forever).",
		["The {item:18703}"] = "{item:18703}",
		["The {object:179703} appears in {area:2717} when {npc:12018} yields; it holds the {item:18703} about half the time. {area:2717} is a 40-player raid inside {area:254}. Right-click the leaf to start the quest."] = "La {object:179703} apparaît dans {area:2717} quand {npc:12018} se rend ; elle contient la {item:18703} environ une fois sur deux. {area:2717} est un raid à 40 joueurs dans {area:254}. Faites un clic droit sur la feuille pour commencer la quête.",
		["Vartrus, Stoma and {npc:14526} stand together in the north of {zone:1448}. Alliance: {area:1998} is the nearest flight point; Horde: {area:1997}."] = "Vartrus, Stoma et {npc:14526} se tiennent ensemble au nord de {zone:1448}. Alliance : {area:1998} est le point de vol le plus proche ; Horde : {area:1997}.",
		["from the {item:18703}"] = "via la {item:18703}",
		["{item:18704}, from {npc:6109}"] = "{item:18704}, sur {npc:6109}",
		["{item:18705}, from Onyxia"] = "{item:18705}, sur Onyxia",
		["{item:18707}, by Vartrus"] = "{item:18707}, par Vartrus",
		["{npc:14524}: Lok'delar in Classic"] = "{npc:14524} : Lok'delar dans Classic",
		["{npc:14526}: the quiver, last in this guide"] = "{npc:14526} : le carquois, en dernier dans ce guide",
		["{npc:14527}, a troll, stands in the west of {zone:1449}. Talk to her and she becomes {npc:14533}, with a pet of her own. Alone, without your pet."] = "{npc:14527}, une trollesse, se tient à l'ouest du {zone:1449}. Parlez-lui et elle devient {npc:14533}, avec son propre familier. Seul, sans votre familier.",
		["{npc:14529}, a human, stands in the west of the {zone:1428}. Talk to him and he becomes {npc:14534}. Alone, without your pet."] = "{npc:14529}, un humain, se tient à l'ouest de {zone:1428}. Parlez-lui et il devient {npc:14534}. Seul, sans votre familier.",
		["{npc:14531}, a tauren, waits in the north-east of {zone:1452}. Talk to him and he becomes {npc:14535}. Fight every demon alone and without your pet: help of any kind makes it vanish. Loot the head."] = "{npc:14531}, un tauren, attend au nord-est de {zone:1452}. Parlez-lui et il devient {npc:14535}. Combattez chaque démon seul et sans votre familier : toute aide le fait disparaître. Récupérez la tête.",
		["{npc:14536}, a gnome, stands in the south-west of {zone:1451}. Talk to him and he becomes {npc:14530}. Alone, without your pet; keep away from the beetles he calls."] = "{npc:14536}, un gnome, se tient au sud-ouest de {zone:1451}. Parlez-lui et il devient {npc:14530}. Seul, sans votre familier ; tenez-vous loin des scarabées qu'il appelle.",
} end)()
t.guides["forever/class/hunter/the-hunters-charm"] = (function() return {
		["At 50 any Alliance hunter trainer offers it: {npc:5516} in {zone:1453}'s {object:28027}, {npc:5116} in {zone:1455}'s {object:32390} or Dorion in {zone:1457}' Cenarion Enclave."] = "Au niveau 50, tout maître des chasseurs de l'Alliance la propose : {npc:5516} dans {object:28027} de {zone:1453}, {npc:5116} dans {object:32390} d'{zone:1455} ou Dorion à l'Enclave cénarienne de {zone:1457}.",
		["At 50 any Horde hunter trainer offers it: {npc:3352} in {zone:1454}'s {object:172958} or {npc:3039} on {area:1641} in {zone:1456}."] = "Au niveau 50, tout maître des chasseurs de la Horde la propose : {npc:3352} dans {object:172958} d'{zone:1454} ou {npc:3039} sur {area:1641}, aux {zone:1456}.",
		["Experience"] = "Expérience",
		["Experience at 50 through {zone:1447} and the {area:1417}; Forever removed the Classic item choice."] = "De l'expérience au niveau 50 via {zone:1447} et {area:1417} ; Forever a supprimé le choix d'objet de Classic.",
		["Morphaz in the {area:1417}"] = "Morphaz dans {area:1417}",
		["Morphaz is an elite dragon boss inside the {area:1417}, a five-player dungeon: bring a group. The temple stands in the middle of the {area:74}; swim down into it to reach the entrance. Horde: fly to {area:75}; Alliance: fly to {area:42} or {area:1438} and ride on."] = "Morphaz est un boss dragon élite dans {area:1417}, un donjon à cinq joueurs : venez en groupe. Le temple se dresse au milieu de {area:74} ; plongez pour atteindre l'entrée. Horde : volez jusqu'à {area:75} ; Alliance : volez jusqu'à {area:42} ou {area:1438} et continuez à monture.",
		["Mosshoof Coursers graze all over {zone:1447}; one in a dozen or so drops a pair of Perfect Courser Antlers."] = "Des Coursiers Sabots-de-mousse ({npc:8761}) paissent partout en {zone:1447} ; environ un sur douze lâche une paire de Ramures de coursier parfaites ({item:20017}).",
		["Wavethrashers crawl along {zone:1447}'s coasts: Young Wavethrashers on the north-east shore and Wavethrashers on the east coast drop the scales about twice as often as the Great Wavethrashers of the south shore."] = "Les Vandales des flots rampent le long des côtes d'{zone:1447} : les Jeunes Vandales des flots de la rive nord-est et les Vandales des flots de la côte est laissent tomber les écailles environ deux fois plus souvent que les Grands Vandales des flots de la rive sud.",
		["{item:20019}, inside the {area:1417}"] = "{item:20019}, dans {area:1417}",
		["{npc:8405} lives atop the cliffs north-east of the {area:1221}. Alliance: fly to {area:3137}; Horde: fly to {area:1237}."] = "{npc:8405} vit au sommet des falaises au nord-est des {area:1221}. Alliance : volez jusqu'à {area:3137} ; Horde : volez jusqu'à {area:1237}.",
		["{quest:8151} (Alliance)"] = "{quest:8151} (Alliance)",
		["{quest:8151} (Horde)"] = "{quest:8151} (Horde)",
} end)()
t.guides["forever/class/mage/arcane-refreshment"] = (function() return {
		["Back to Lydros"] = "Retour auprès de Lydros",
		["Fly to Feathermoon (Alliance) or {area:1099} (Horde) and ride to {area:2577} in central {zone:1444}. {npc:14368} waits in the Athenaeum, the library, reached through the West wing (or the North wing with a {item:18249})."] = "Prenez un vol pour Pennelune (Alliance) ou {area:1099} (Horde) et rendez-vous à {area:2577}, au centre de {zone:1444}. {npc:14368} attend dans l'Athenaeum, la bibliothèque, accessible par l'aile Ouest (ou par l'aile Nord avec une {item:18249}).",
		["Hydrospawn"] = "Hydrogénos",
		["Hydrospawn, a water elemental, lives in the Warpwood Quarter (Dire Maul East): chase the imp Pusillin until he turns to fight, clear the satyr room, then take the spiral ramp down to the pool."] = "Hydrogénos, un élémentaire d'eau, vit dans le quartier Crochebois (Hache-tripes Est) : poursuivez le diablotin Pusillin jusqu'à ce qu'il se retourne pour combattre, nettoyez la salle des satyres, puis descendez la rampe en spirale jusqu'au bassin.",
		["Shen'dralar reputation"] = "Réputation Shen'dralar",
		["The level 60 {spell:10140}, from a {area:2577} library: drink for you and your group."] = "{spell:10140} de niveau 60, tiré d'une bibliothèque de {area:2577} : de quoi boire pour vous et votre groupe.",
		["{item:18299}: Hydrospawn"] = "{item:18299} : Hydrogénos",
} end)()
t.guides["forever/class/mage/astral-knot-garment"] = (function() return {
		["A robe or a blouse for Human and Gnome mages in their late 20s."] = "Une robe ou une blouse pour les mages humains et gnomes vers la fin de la vingtaine de niveaux.",
		["Back to Andromath"] = "Retour auprès d'Andromath",
		["Carrion Recluses"] = "Solitaires putrides",
		["Carrion Recluses lurk in the woods of western {zone:1431} and each one drops the silk. The Black Widow Hatchlings further east drop it now and then."] = "Les Solitaires putrides rôdent dans les bois de l'ouest du {zone:1431} et chacun laisse tomber la soie. Les Jeunes veuves noires plus à l'est la laissent tomber de temps en temps.",
		["Ride east through {zone:1429} into Redridge. The fallen mage's tower of Ilgalar stands in the east of the zone; the treatise is in his library."] = "Traversez la {zone:1429} vers l'est jusqu'aux Carmines. La tour du mage déchu Ilgalar se dresse à l'est de la zone ; le traité est dans sa bibliothèque.",
		["The {area:96}"] = "La {area:96}",
		["{npc:1309} works at {object:23296} in the {object:2101}."] = "{npc:1309} travaille chez {object:23296}, dans le {object:2101}.",
		["{npc:5144} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards."] = "{npc:5144} forme les mages dans le {object:32362} d'{zone:1455}. Prenez ensuite le {area:2257} depuis {object:171524} jusqu'à {zone:1453}.",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}."] = "{npc:5497} se tient dans le Sanctuaire du Sorcier, la tour du {object:2101}.",
		["{quest:1939} is in the Wizard's Sanctum too."] = "{quest:1939} se trouve aussi dans le Sanctuaire du Sorcier.",
} end)()
t.guides["forever/class/mage/celestial-orb"] = (function() return {
		["An off-hand orb or a staff for the late 30s, your pick."] = "Un orbe de main gauche ou un bâton pour la fin des 30, au choix.",
		["Back to {npc:6546}. She opens a mana rift beside her cottage: kill twelve {quest:1957} within ten minutes."] = "Retournez voir {npc:6546}. Elle ouvre une faille de mana à côté de sa chaumière : tuez douze {quest:1957} en dix minutes.",
		["The Burning Blade Summoners work the {area:602} in southern {zone:1443}; any of them carries an {item:7291}."] = "Les Invocateurs de la Lame ardente officient à {area:602}, dans le sud de {zone:1443} ; chacun d'eux porte {item:7291}.",
		["{area:1517} is a dungeon in the northern {zone:1418}, by the {object:178824}: a group of five. Defeat the {npc:7023} inside for its power source."] = "{area:1517} est un donjon au nord de {zone:1418}, près de {object:178824} : un groupe de cinq. Vainquez {npc:7023} à l'intérieur pour sa source d'énergie.",
		["{item:7515} and Stave"] = "{item:7515} et Bâton céleste",
		["{npc:5497} in the Wizard's Sanctum, {zone:1453}'s {object:2101}, sends you back to {npc:6546}; Bink in {zone:1455} gives the same quest."] = "{npc:5497}, au Sanctuaire des sorciers dans {object:2101} de {zone:1453}, vous renvoie voir {npc:6546} ; Bink, à {zone:1455}, donne la même quête.",
		["{npc:5885}, one of {zone:1454}'s mage trainers, sends you back to {npc:6546}; {npc:4568} in the {zone:1458} and {npc:3048} in {zone:1456} give the same quest."] = "{npc:5885}, l'un des maîtres des mages d'{zone:1454}, vous renvoie voir {npc:6546} ; {npc:4568} à {zone:1458} et {npc:3048} à {zone:1456} donnent la même quête.",
		["{npc:6546} draws the demon out of the orb beside her cottage. The {npc:6549} is elite: grouping up is advised. You have three minutes before it slips back into the orb."] = "{npc:6546} fait sortir le démon de l'orbe à côté de sa chaumière. {npc:6549} est élite : il est conseillé de grouper. Vous avez trois minutes avant qu'il ne retourne dans l'orbe.",
		["{npc:6546}'s cottage is deep in the marsh west of Theramore, just north of the {area:508}."] = "La chaumière de {npc:6546} est au fond du marais à l'ouest de Theramore, juste au nord de {area:508}.",
} end)()
t.guides["forever/class/mage/destroy-morphaz"] = (function() return {
		["Back to {npc:8395} and up to the tower."] = "Retournez voir {npc:8395} et montez dans la tour.",
		["Back to {npc:8395}, who teleports you up to the tower."] = "Retournez voir {npc:8395}, qui vous téléporte dans la tour.",
		["Back to {zone:1447}, {npc:8395} and the tower."] = "Retournez en {zone:1447}, auprès de {npc:8395} et à la tour.",
		["Experience"] = "Expérience",
		["Experience at 50 through {zone:1447} and the {area:1417}; Forever removed the Classic item choice."] = "De l'expérience au niveau 50 via {zone:1447} et {area:1417} ; Forever a supprimé le choix d'objet de Classic.",
		["Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below his master's tower: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. He teleports you up to {npc:8379}."] = "Volez jusqu'à {area:3137} (Alliance) ou {area:1237} (Horde). {npc:8395} campe au pied de la tour de son maître : depuis la fourche de la route principale d'{zone:1447}, à {area:1221}, allez droit au nord jusqu'aux falaises. Il vous téléporte auprès de {npc:8379}.",
		["Morphaz"] = "Morphaz",
		["Morphaz, a green drake, waits deep in the {area:1477}, the {area:1417} in the {area:74}: a group of five, level 50-54. Kill him for the {item:20085}."] = "Morphaz, un drake vert, attend au fond de {area:1477}, {area:1417} dans {area:74} : groupe de cinq, niveaux 50-54. Tuez-le pour {item:20085}.",
		["The Spitelash Sirens walk the ruins and beaches around the {area:1221} and the bay; they carry the coral."] = "Les Sirènes Fouette-bile arpentent les ruines et les plages autour de {area:1221} et de la baie ; elles portent le corail.",
		["The blood elves camp along the cliffs of north-eastern {zone:1447}; Blood Elf Surveyors and Reclaimers drop the dust."] = "Les elfes de sang campent le long des falaises au nord-est d'{zone:1447} ; les Géomètres et Vengeurs elfes de sang lâchent la poussière.",
		["The {item:20085}"] = "{item:20085}",
		["{item:20085}: Morphaz"] = "{item:20085} : Morphaz",
		["{npc:331}, the Master Mage, stands in the Wizard's Sanctum in {zone:1453}'s {object:2101}; Dink in {zone:1455} gives the same quest."] = "{npc:331}, le maître des mages, se tient dans la tour de {object:2101} de {zone:1453} ; Dink, à {zone:1455}, donne la même quête.",
		["{npc:7311}, one of {zone:1454}'s mage trainers, gives it; so do {npc:4567} in the {zone:1458} and {npc:3047} in {zone:1456}."] = "{npc:7311}, l'un des maîtres des mages d'{zone:1454}, la donne ; tout comme {npc:4567} à {zone:1458} et {npc:3047} à {zone:1456}.",
		["{npc:8379} again"] = "De nouveau {npc:8379}",
		["{npc:8379}, in the tower"] = "{npc:8379}, dans la tour",
} end)()
t.guides["forever/class/mage/ju-ju-heaps"] = (function() return {
		["A staff or an orb at 10 for Horde mages, worth a short trip back to the {area:368}."] = "Un bâton ou un orbe au niveau 10 pour les mages de la Horde, qui vaut un petit retour aux {area:368}.",
		["Back to Un'thuwa"] = "Retour auprès d'Un'Thuwa",
		["The {quest:1884}"] = "{quest:1884}",
		["Un'thuwa"] = "Un'Thuwa",
		["Un'thuwa stands in {area:367}, on the {zone:1411} coast south of {area:362}."] = "Un'Thuwa se tient au {area:367}, sur la côte de {zone:1411} au sud de {area:362}.",
		["Wade across to the {area:368}, south-east of Sen'jin. Zalazane placed the heaps among his huts on the main isle: click a heap to destroy it."] = "Traversez à gué jusqu'aux {area:368}, au sud-est du Village de Sen'jin. Zalazane a placé les tas parmi ses huttes sur l'île principale : cliquez sur un tas pour le détruire.",
} end)()
t.guides["forever/class/mage/mages-wand"] = (function() return {
		["\"Plucky\" Johnson"] = "Johnson « le Brave »",
		["A wand of your school for the 30s: frost, arcane or fire."] = "Une baguette de votre école pour les niveaux 30 : givre, arcanes ou feu.",
		["Back to {npc:6546}"] = "Retournez voir {npc:6546}",
		["The Witherbark trolls hold south-eastern {zone:1417}; every one of them can drop a {item:7273}. Then take the ten sticks north-west to the binding circle where they become the {item:7272}. {npc:6546} also wants a {item:1529}: buy one at an Auction House on the way; miners sometimes find one in Tin Veins."] = "Les Trolls fanécorce occupent le sud-est des {zone:1417} ; chacun peut laisser tomber un {item:7273}. Portez ensuite les dix bâtons au nord-ouest jusqu'au cercle de lien, où ils deviennent la {item:7272}. {npc:6546} veut aussi une {item:1529} : achetez-en une dans un hôtel des ventes en chemin ; les mineurs en trouvent parfois dans les Filons d'étain.",
		["Tirth sold the book to the Scarlet Brotherhood. The {area:796} stands in north-eastern {zone:1420}; take the Library wing. The book juts out of the wall on the left as you enter the Athenaeum, before {npc:6487}."] = "Tirth a vendu le livre à la Croisade écarlate. Le {area:796} se dresse au nord-est de {zone:1420} ; prenez l'aile de la Bibliothèque. Le livre dépasse du mur à gauche en entrant dans l'Athenaeum, avant {npc:6487}.",
		["Tirth's apprentice is \"Plucky\" Johnson, a small grey chicken by the race track. Target him and type /beckon: he turns human for a moment, long enough to talk to him."] = "L'apprenti de Tirth est Johnson « le Brave », un petit poulet gris près de la piste de course. Ciblez-le et tapez /beckon : il redevient humain un instant, le temps de lui parler.",
		["Witherbark trolls"] = "Trolls fanécorce",
		["{npc:5497} in the Wizard's Sanctum, {zone:1453}'s {object:2101}, sends you to {npc:6546}; Bink in {zone:1455} gives the same quest."] = "{npc:5497}, dans la tour du {object:2101} de {zone:1453}, vous envoie voir {npc:6546} ; Bink, à {zone:1455}, donne la même quête.",
		["{npc:5885}, one of {zone:1454}'s mage trainers, sends you to {npc:6546}; {npc:4568} in the {zone:1458} and {npc:3048} in {zone:1456} give the same quest."] = "{npc:5885}, l'un des maîtres des mages d'{zone:1454}, vous envoie voir {npc:6546} ; {npc:4568} à {zone:1458} et {npc:3048} aux {zone:1456} donnent la même quête.",
		["{npc:6546}'s ritual"] = "Le rituel de {npc:6546}",
		["{npc:6546}, a hermit, lives in a cottage deep in the marsh west of Theramore, just north of the {area:508}."] = "{npc:6546}, une ermite, vit dans une chaumière au fond du marais à l'ouest de Theramore, juste au nord des {area:508}.",
		["{npc:6548} spends his days at the race track in the {area:439}, south-east {zone:1441}."] = "{npc:6548} passe ses journées sur la piste de course de {area:439}, au sud-est de {zone:1441}.",
