t.guides["forever/class/paladin/lumina-windsinger"] = (function() return {
		["Back to the {area:228}"] = "Retour au {area:228}",
		["Free her with the key, then stay close while she fights her way out of the keep."] = "Libérez-la avec la clé, puis restez près d'elle pendant qu'elle se fraie un chemin hors du donjon.",
		["Free {npc:248755}"] = "Libérer {npc:248755}",
		["No item yet: a Forsaken paladin rescue story; its sequel, the {item:268484}, cannot be finished yet."] = "Pas encore d'objet : une histoire de sauvetage pour paladin réprouvé ; sa suite, la {item:268484}, ne peut pas encore être terminée.",
		["Once she is clear of {area:235}, {npc:259620} waits for you in the {area:228}. Speak with her again to hear what really happened on the road."] = "Une fois sortie de {area:235}, {npc:259620} vous attend au {area:228}. Parlez-lui de nouveau pour apprendre ce qui s'est vraiment passé sur la route.",
		["Rescuing {quest:91862}"] = "Secourir {quest:91862}",
		["Ride south through {zone:1421} to the {area:228}. {npc:248840} stands in the town; {npc:259611} keeps watch near its entrance."] = "Allez vers le sud à travers {zone:1421} jusqu'au {area:228}. {npc:248840} se trouve dans le bourg ; {npc:259611} monte la garde près de l'entrée.",
		["The pyre on {area:172}"] = "Le bûcher de {area:172}",
		["from the {object:566037}"] = "sur {object:566037}",
		["{area:172} lies in the lake east of the {area:228}. The charred remains are on its shore."] = "{area:172} se trouve dans le lac à l'est du {area:228}. Les restes calcinés sont sur sa rive.",
		["{item:267412}, from the Rot Hide gnolls"] = "{item:267412}, sur les gnolls Poil-Putride",
		["{npc:246378} leads the Paladins of Tyr's Watch from inside {area:16602}, on the bluffs north-west of the {area:156}."] = "{npc:246378} dirige les paladins de Tyr's Watch depuis {area:16602}, sur les hauteurs au nord-ouest de la {area:156}.",
		["{npc:259620}, the {area:228}"] = "{npc:259620}, au {area:228}",
		["{quest:91862} is caged inside {area:235}, at the north end of the isle. The Rot Hide gnolls around her carry the key."] = "{quest:91862} est enfermée dans une cage à l'intérieur de {area:235}, à l'extrémité nord de l'île. Les gnolls Poil-Putride autour d'elle portent la clé.",
		["{zone:1458} and Earthen Ring reputation"] = "Réputation auprès de {zone:1458} et du Cercle terrestre",
} end)()
t.guides["forever/class/paladin/tyrs-watch"] = (function() return {
		["Back to the keep"] = "Retour au donjon",
		["Back to {area:16602}. {npc:246378} gives you the {item:6866}; {npc:257655} waits downstairs in the keep."] = "Retour à {area:16602}. {npc:246378} vous remet le {item:6866} ; {npc:257655} attend au rez-de-chaussée du donjon.",
		["Back to {area:16602}: Billmuth takes the plans, {npc:246378} teaches you {spell:7328}."] = "Retour à {area:16602} : Billmuth prend les plans, {npc:246378} vous apprend {spell:7328}.",
		["Tarnished Drudges"] = "Manoeuvres ternis",
		["Tarnished Zealots"] = "Zélotes ternis",
		["The Scarlet Crusaders camped around {area:812} carry the attack plans."] = "Les membres de la Croisade écarlate qui campent autour de la {area:812} portent les plans d'attaque.",
		["The Scarlet attack plans"] = "Les plans d'attaque de la Croisade écarlate",
		["The Vile Fin murlocs lurk on the bluffs along the road east of the keep and in the camps around the lake to the west."] = "Les murlocs Aileron noir rôdent sur les falaises le long de la route à l'est du donjon et dans les camps autour du lac à l'ouest.",
		["The {item:6866}"] = "Le {item:6866}",
		["Tyr's Watch and {spell:7328}"] = "Tyr's Watch et {spell:7328}",
		["Vile Fin Attackers"] = "Attaquants aileron noir",
		["Vile Fin Seers"] = "Oracles aileron noir",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:10181} holds court in the {object:36126}; {npc:257648} begs in the {object:36078}."] = "Marchez vers le sud depuis {area:159} jusqu'aux {area:153} et descendez dans {zone:1458}. {npc:10181} tient sa cour dans le {object:36126} ; {npc:257648} mendie dans le {object:36078}.",
		["{area:16602} stands on the bluffs north-west of the {area:156}. {npc:246349} waits at the gate."] = "{area:16602} se dresse sur les falaises au nord-ouest de la {area:156}. {npc:246349} attend à la porte.",
		["{area:812} is at the far east end of the glades. Use the {item:6866} on {npc:257663}, then speak to him. If you lose the symbol, {npc:246378} gives you another."] = "La {area:812} se trouve à l'extrémité est des clairières. Utilisez le {item:6866} sur {npc:257663}, puis parlez-lui. Si vous perdez le symbole, {npc:246378} vous en donne un autre.",
		["{npc:246152}, who trains Paladins in {area:159}, sends you to the order's keep on the west coast."] = "{npc:246152}, qui forme les paladins à {area:159}, vous envoie au donjon de l'ordre sur la côte ouest.",
		["{npc:246378} leads the order from inside the keep; {npc:246393} stands beside it."] = "{npc:246378} dirige l'ordre depuis l'intérieur du donjon ; {npc:246393} se tient à côté.",
		["{npc:246378} offers the first Lesson in Divinity at level 12."] = "{npc:246378} propose la première Leçon de divinité au niveau 12.",
		["{npc:257648} needs 10 {item:2589}. Scarlet Zealots and Scarlet Friars drop it about three times in ten; bring it along if you already carry some."] = "{npc:257648} a besoin de 10 {item:2589}. Les Zélotes écarlates et les Frères écarlates en laissent tomber environ trois fois sur dix ; apportez-en si vous en avez déjà.",
		["{object:554626}, in the root cellar"] = "{object:554626}, dans le cellier",
		["{quest:91317} hold the ruined village of {area:16881} in the {area:16616}, south-west of the keep. The {item:246213} is piled in the root cellar of one of its houses; Commander {npc:259431} walks among his Tarnished."] = "{quest:91317} occupent le village en ruine de {area:16881}, dans la {area:16616}, au sud-ouest du donjon. Le {item:246213} est empilé dans le cellier de l'une de ses maisons ; le commandant {npc:259431} circule parmi ses Ternis.",
		["{spell:7328} to raise fallen allies, plus a weapon and a shield for a new Forsaken paladin."] = "{spell:7328} pour ranimer les alliés tombés, plus une arme et un bouclier pour un nouveau paladin réprouvé.",
} end)()
t.guides["forever/class/paladin/verigans-fist"] = (function() return {
		["At 20 {npc:6179} in the {object:32362} gives you the {item:6776}; it sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. Take the tram from {zone:1455} to {zone:1453}."] = "Au niveau 20, {npc:6179}, dans {object:32362}, vous remet le {item:6776} ; il vous envoie voir {npc:6171} dans la Cathedral of Light de {zone:1453}. Prenez le tram de {zone:1455} à {zone:1453}.",
		["Back to {npc:3649} in {area:442}: he purifies the gem."] = "Retournez voir {npc:3649} à {area:442} : il purifie la gemme.",
		["Back to {npc:6241}"] = "Retour à {npc:6241}",
		["Bring the four parts to {npc:6181} outside {zone:1455}."] = "Apportez les quatre pièces à {npc:6181}, devant {zone:1455}.",
		["Goblin Woodcarvers, inside"] = "Sculpteurs gobelins, à l'intérieur",
		["Protect {npc:6182}"] = "Protégez {npc:6182}",
		["The Alliance paladin's rare two-handed mace for the 20s, with a shield on the way."] = "La rare masse à deux mains des paladins de l'Alliance pour les niveaux 20+, avec un bouclier en chemin.",
		["The Blackfathom naga by the entrance of {area:2797} on {zone:1440}'s north-west coast drop the {item:6995}. They are elite: grouping up is advised."] = "Les nagas de Brassenoire près de l'entrée de {area:2797}, sur la côte nord-ouest d'{zone:1440}, laissent tomber la {item:6995}. Ils sont élites : un groupe est conseillé.",
		["The ore crate lies by the trees in the middle of the Mo'grosh ogre camp in north-east {zone:1432}. The Mo'grosh ogres are elite: grouping up is advised."] = "La caisse de minerai se trouve près des arbres, au milieu du camp des ogres Mo'grosh, au nord-est du {zone:1432}. Les ogres Mo'grosh sont élites : un groupe est conseillé.",
		["The {item:6995}"] = "La {item:6995}",
		["The {item:7083}"] = "La {item:7083}",
		["from the {item:6776}"] = "via le {item:6776}",
		["{area:1581} is a group of five under {area:20}; the instance portal is inside the {area:20} mine. The Goblin Woodcarvers in the Mast Room, with Sneed, drop the lumber."] = "{area:1581} est un donjon à cinq sous {area:20} ; le portail se trouve dans la mine de {area:20}. Les Sculpteurs gobelins de la salle du mât, avec Sneed, laissent tomber le bois.",
		["{area:1581}, in the {area:20} mine"] = "{area:1581}, dans la mine de {area:20}",
		["{area:236} is a level 20-30 dungeon in southern {zone:1421}. The hammer lies on a box inside the stables, at the far end of the courtyard before the ramp up."] = "{area:236} est un donjon de niveau 20-30 au sud de {zone:1421}. Le marteau repose sur une caisse dans les écuries, au fond de la cour, avant la rampe.",
		["{npc:3649} is in {area:442}."] = "{npc:3649} est à {area:442}.",
		["{npc:6171} stands in the Cathedral of Light. Right-click the {item:6776} to start its quest."] = "{npc:6171} se tient dans la Cathedral of Light. Faites un clic droit sur le {item:6776} pour commencer sa quête.",
		["{npc:6181} stands outside the gates of {zone:1455}. He gives you {item:6996}, which list the four parts."] = "{npc:6181} se tient devant les portes de {zone:1455}. Il vous remet les {item:6996}, qui listent les quatre pièces.",
		["{npc:6182}'s farmhouse stands on the south-west coast of {zone:1436}. Waves of Defias attack it during her quest: keep her alive, and heal her if she needs it."] = "La ferme de {npc:6182} se trouve sur la côte sud-ouest de {zone:1436}. Des vagues de Défias l'attaquent pendant sa quête : gardez-la en vie et soignez-la si besoin.",
		["{npc:6241} is in {area:144}."] = "{npc:6241} est à {area:144}.",
