		["{quest:63} (Horde)"] = "{quest:63} (Horde)",
} end)()
t.guides["forever/class/shaman/darkreaver"] = (function() return {
		["200 Horde reputation"] = "200 de réputation Horde",
		["A {area:2057} fight at 60 for Horde reputation; Forever removed the {item:20134}."] = "Un combat à {area:2057} au niveau 60 pour de la réputation Horde ; Forever a supprimé {item:20134}.",
		["An {item:12800} comes from Thorium veins, a {item:18335} from the elites of the {zone:1422}, both rarely: buy them at the auction house if you can."] = "Un {item:12800} provient des filons de thorium, un {item:18335} des élites des {zone:1422}, tous deux rarement : achetez-les à l'Hôtel des ventes si vous pouvez.",
		["At 58 {npc:13417}, the shaman trainer in the {object:172957}, asks for two rare diamonds."] = "Au niveau 58, {npc:13417}, le maître des chamans de {object:172957}, demande deux diamants rares.",
		["Two diamonds"] = "Deux diamants",
		["he hands you the {item:18746}"] = "il vous remet {item:18746}",
		["{area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}. Use the {item:18746} in the heart of the {object:179746}'s basement, beat the spirits it calls, then {npc:14516}. All are elite: bring a group."] = "{area:2057} se trouve sous {area:2298}, la ville sur l'île au sud-est des {zone:1422}. Utilisez {item:18746} au cœur du sous-sol du Grand ossuaire, battez les esprits qu'il appelle, puis {npc:14516}. Tous sont élites : venez en groupe.",
		["{quest:7668} needs level 60."] = "{quest:7668} demande le niveau 60.",
} end)()
t.guides["forever/class/shaman/spirit-totem"] = (function() return {
		["At 50 {npc:13417}, the shaman trainer in the {object:172957}, sends you to {npc:6176}."] = "Au niveau 50, {npc:13417}, le maître des chamans de la {object:172957}, vous envoie voir {npc:6176}.",
		["At 50 {npc:3032}, a shaman trainer in {zone:1456}, sends you to {npc:6176}."] = "Au niveau 50, {npc:3032}, maître des chamans à {zone:1456}, vous envoie voir {npc:6176}.",
		["Experience and gold"] = "Expérience et or",
		["Experience and gold at 50, ending in the {area:1417}; Forever removed the Classic item choice."] = "De l'expérience et de l'or au niveau 50, avec une fin dans le {area:1417} ; Forever a supprimé le choix d'objet de Classic.",
		["In the {zone:1422}, the Venom Mist Lurkers drop the {item:20610} and the Diseased Black Bears the {item:20611} (about one kill in five each)."] = "Dans les {zone:1422}, les Rôdeuses venimeuses des brumes laissent tomber l'{item:20610} et les Ours noirs malades la {item:20611} (environ une fois sur cinq chacun).",
		["One each of {item:7069}, Fire, Earth and Water. The Exiles of Arathi Highlands drop them, one element each, about one kill in ten: Thundering (air), Burning (fire), Rumbling (earth) and Cresting (water). Or buy them at the auction house."] = "Un exemplaire de chacun : {item:7069}, Feu élémentaire, Terre élémentaire et Eau élémentaire. Les Exilés des Hautes-terres Arathies les laissent tomber, un élément chacun, environ une fois sur dix : Exilés foudroyants (air), ardents (feu), grondants (terre) et grimpeurs (eau). Ou achetez-les à l'hôtel des ventes.",
		["Spider eye and bear claw"] = "Œil d'araignée et griffe d'ours",
		["The four elements"] = "Les quatre éléments",
		["The {area:1417}"] = "Le {area:1417}",
		["The {area:1417} ({area:1477}) lies under the {area:74}; the arrow points at its entrance. Gasher or {npc:5716} drop the {item:20606}, Hukku or Mijan the Blue, Zolo or Loro the Green: all six are elite trolls inside. Bring a group."] = "Le {area:1417} ({area:1477}) se trouve sous le {area:74} ; la flèche indique son entrée. Balafreur ou {npc:5716} laissent tomber la {item:20606}, Hukku ou Mijan la bleue, Zolo ou Loro la verte : tous les six sont des trolls élites à l'intérieur. Venez en groupe.",
		["{item:7067}: Rumbling Exiles"] = "{item:7067} : Exilés grondants",
		["{item:7068}: Burning Exiles"] = "{item:7068} : Exilés ardents",
		["{item:7069}: Thundering Exiles"] = "{item:7069} : Exilés foudroyants",
		["{item:7070}: Cresting Exiles"] = "{item:7070} : Exilés grimpeurs",
		["{npc:6176} camps in the east of {zone:1416}, north-east of {area:272}."] = "{npc:6176} campe dans l'est des {zone:1416}, au nord-est de {area:272}.",
		["{quest:8412} and {quest:8413}"] = "{quest:8412} et {quest:8413}",
} end)()
t.guides["forever/class/warlock/enchanted-gold-bloodrobe"] = (function() return {
		["A rare cloth robe for your 30s, which {npc:6266} makes from the parts you bring her."] = "Une robe en tissu rare pour vos niveaux 30, que {npc:6266} confectionne avec les pièces que vous lui apportez.",
		["At 31 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "Au niveau 31, {npc:3326}, dans {object:172960}, vous envoie voir {npc:6266} à {area:392}.",
		["At 31 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "Au niveau 31, {npc:4563}, dans {object:36082}, vous envoie voir {npc:6266} à {area:392}. Le zeppelin de {zone:1420} va à {zone:1411}.",
		["At 31 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "Au niveau 31, {npc:461}, à {object:2164} dans {object:2101}, vous envoie voir {npc:6266} à {area:392}.",
		["At 31 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "Au niveau 31, {npc:5172} à {zone:1455} vous envoie voir {npc:6266} à {area:392}.",
		["Back to {npc:6266}"] = "Retour auprès de {npc:6266}",
		["Back to {npc:6266} with the thread, the coal and a {item:6265}. Wait while she completes the robe, then speak to her again."] = "Retournez voir {npc:6266} avec le fil, le charbon et un {item:6265}. Attendez qu'elle termine la robe, puis parlez-lui de nouveau.",
		["Bring {npc:6266} a {item:5770}: tailors sew it from a pattern that drops; otherwise buy one at the Auction House. Her next errand needs a {item:3577}: smelted from {item:2776}, or from the Auction House."] = "Apportez à {npc:6266} une {item:5770} : les tailleurs la cousent à partir d'un patron trouvé sur les monstres ; sinon, achetez-en une à l'hôtel des ventes. Sa course suivante demande un {item:3577} : fondu à partir de {item:2776}, ou acheté à l'hôtel des ventes.",
		["The Burning Exiles, fire elementals in western {zone:1417}, drop the coal."] = "Les Exilés ardents, des élémentaires de feu de l'ouest de {zone:1417}, laissent tomber le charbon.",
		["The Hatefury satyrs of {area:603}, in north-eastern {zone:1443}, carry the blood; the Lesser Infernals of Mannoroc Coven, in the south, the stone."] = "Les satyres Fielfurie de {area:603}, dans le nord-est de {zone:1443}, portent le sang ; les Infernaux mineurs du Convent de Mannoroc, au sud, la pierre.",
		["Vials of Hatefury Blood"] = "Fioles de sang de Fielfurie",
		["Wait for the robe"] = "Attendre la robe",
		["{npc:2670} in {area:35} has the thread for you."] = "{npc:2670} à {area:35} a le fil pour vous.",
		["{npc:2670} sells tailoring supplies in {area:35}. Bring him the {item:3577}."] = "{npc:2670} vend des fournitures de couture à {area:35}. Apportez-lui le {item:3577}.",
		["{npc:6266} again"] = "Encore {npc:6266}",
		["{npc:6266} stands in the tower on the hill above {area:392}, beside {npc:6251}."] = "{npc:6266} se trouve dans la tour sur la colline au-dessus de {area:392}, à côté de {npc:6251}.",
		["{zone:1443} demons"] = "Démons de {zone:1443}",
} end)()
