t.guides["forever/class/warlock/impsys-request"] = (function() return {
		["A staff, off-hand or robe for your 50s; {npc:14470}'s own errand, not a step of the Dreadsteed chain."] = "Un bâton, une main gauche ou une robe pour vos niveaux 50 ; une mission propre à {npc:14470}, pas une étape de la chaîne du Destrier de l'effroi.",
		["At 50 {npc:3326} in the {object:172960} sends you to {npc:14470} in {zone:1448}."] = "Au niveau 50, {npc:3326}, à {object:172960}, vous envoie voir {npc:14470} en {zone:1448}.",
		["At 50 {npc:4563} in the {object:36082} sends you to {npc:14470} in {zone:1448}."] = "Au niveau 50, {npc:4563}, à {object:36082}, vous envoie voir {npc:14470} en {zone:1448}.",
		["At 50 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:14470} in {zone:1448}."] = "Au niveau 50, {npc:461}, à {object:2164}, dans {object:2101}, vous envoie voir {npc:14470} en {zone:1448}.",
		["At 50 {npc:5172} in {zone:1455} sends you to {npc:14470} in {zone:1448}."] = "Au niveau 50, {npc:5172}, à {zone:1455}, vous envoie voir {npc:14470} en {zone:1448}.",
		["The Irontree treants in northern {zone:1448} drop the {item:20613}; the Tainted Oozes around {area:1763} the {item:20614}."] = "Les tréants Arbrefer du nord de {zone:1448} laissent {item:20613} ; les Limons corrompus autour de {area:1763}, {item:20614}.",
		["The six troll guardians of the {area:1417}, a level 50 dungeon, each drop a Voodoo Feather: bring a group of five. The temple stands in the middle of the {area:74}; swim down into it to reach the entrance."] = "Les six gardiens trolls de {area:1417}, un donjon de niveau 50, laissent chacun une plume vaudou : venez à cinq. Le temple se dresse au milieu de {area:74} ; plongez pour en atteindre l'entrée.",
		["The {area:1417}"] = "{area:1417}",
		["{item:20613} and Bloodvenom"] = "{item:20613} et Vénéneuse",
		["{npc:14470} again"] = "De nouveau {npc:14470}",
		["{npc:14470} waits beside {npc:14469} in central {zone:1448}, just east of {area:1763}. This chain is {npc:14470}'s own and is not part of the Dreadsteed chain; Niby and {npc:14470} also give the {item:18762} chain here."] = "{npc:14470} attend à côté de {npc:14469}, au centre de {zone:1448}, juste à l'est de {area:1763}. Cette chaîne est propre à {npc:14470} et ne fait pas partie de la chaîne du Destrier de l'effroi ; Niby le Tout-puissant et {npc:14470} donnent aussi ici la chaîne de {item:18762}.",
		["{npc:14470} wants one {item:14256}: the Jadefire satyrs and the demons of {area:1763} drop it."] = "{npc:14470} veut une {item:14256} : les satyres Jadefeu et les démons de {area:1763} en laissent.",
} end)()
t.guides["forever/class/warlock/incubus-alliance"] = (function() return {
		["A second seducer demon, the male sayaad, and a soul shard bag to carry your shards."] = "Un second démon séducteur, le sayaad mâle, et un sac d'éclats d'âme pour transporter vos éclats.",
		["At 20 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6244} in the {zone:1413}."] = "Au niveau 20, {npc:6122}, dans la cave de {object:2164} dans {object:2101}, vous envoie voir {npc:6244} dans {zone:1413}.",
		["Back to {npc:6122} in the {object:2164}. Place the figurine at the summoning circle in the crypt below him and defeat the incubus it calls."] = "Retournez voir {npc:6122} à {object:2164}. Posez la figurine sur le cercle d'invocation de la crypte sous lui et vainquez l'incube qu'elle appelle.",
		["From {area:415} take the road west to {area:413}: the figurine lies in a house among the trees north of the post."] = "Depuis {area:415}, prenez la route vers l'ouest jusqu'à {area:413} : la figurine se trouve dans une maison parmi les arbres au nord du poste.",
		["Incubus (Alliance)"] = "Incube (Alliance)",
		["{npc:6122}: he binds the incubus to you"] = "{npc:6122} : il vous lie l'incube",
		["{npc:6244} camps in the southern {zone:1413}, east of the road north-east of {area:378}: come in from the east and keep clear of the Horde guards."] = "{npc:6244} campe dans le sud de {zone:1413}, à l'est de la route au nord-est de {area:378} : arrivez par l'est et évitez les gardes de la Horde.",
} end)()
t.guides["forever/class/warlock/incubus-horde"] = (function() return {
		["A second seducer demon, the male sayaad, and a soul shard bag to carry your shards."] = "Un second démon séducteur, le sayaad mâle, et un sac de fragments d'âme pour porter vos fragments.",
		["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers offer the incubus, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one: this guide follows whichever {quest:1472} you took."] = "Au niveau 20, {npc:5875}, dans la {object:172960} sous la {object:172982}, vous envoie voir {npc:5909} à quelques pas. Deux maîtres proposent l'incube, {npc:5875} ici et {npc:5675} à {zone:1458}, et vous ne pouvez en prendre qu'un : ce guide suit la quête {quest:1472} que vous avez prise.",
		["Back to {npc:5675} in the {object:36082}. Place the hearts at the summoning circle below him and defeat the incubus they call."] = "Retournez voir {npc:5675} dans le {object:36082}. Placez les cœurs sur le cercle d'invocation en dessous de lui et vainquez l'incube qu'ils appellent.",
		["Back to {npc:5875} in the {object:172960}. Take the scarf to the summoning circle in {npc:3216}'s tent nearby and defeat the incubus it calls."] = "Retournez voir {npc:5875} dans la {object:172960}. Apportez l'écharpe au cercle d'invocation dans la tente de {npc:3216}, tout près, et vainquez l'incube qu'elle appelle.",
		["Incubus (Horde)"] = "Incube (Horde)",
		["{area:422} lies in southern {zone:1440}, south of {area:431}. The Shadethicket bog beasts around the lake drop the {item:190232}, about one in twenty."] = "Le {area:422} se trouve dans le sud d'{zone:1440}, au sud du {area:431}. Les bêtes des tourbières Sombretaillis autour du lac laissent tomber l'{item:190232}, environ une fois sur vingt.",
		["{npc:185333} works as a tailor for the {area:279} wizards at {area:233}, in eastern {zone:1421}. Take her heart."] = "{npc:185333} travaille comme couturière pour les sorciers de {area:279} à {area:233}, dans l'est de la {zone:1421}. Prenez son cœur.",
		["{npc:185334} works in {area:392}, on the {zone:1413} coast. Take the zeppelin to {zone:1411} and ride or fly on to {area:392}."] = "{npc:185334} travaille à {area:392}, sur la côte des {zone:1413}. Prenez le zeppelin jusqu'à {zone:1411}, puis continuez à monture ou en vol jusqu'à {area:392}.",
		["{npc:3363} keeps {object:173018}, east of the {object:172960} along the main street. He asks you to look for his mate, Krilge."] = "{npc:3363} tient {object:173018}, à l'est de la {object:172960}, le long de la rue principale. Il vous demande de chercher sa compagne, Krilge.",
		["{npc:5675}: he binds the incubus to you"] = "{npc:5675} : il vous lie l'incube",
		["{npc:5875}: he binds the incubus to you"] = "{npc:5875} : il vous lie l'incube",
		["{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} in the Temple of the Damned, just north of him."] = "La version de {object:1661}, pour les démonistes qui ont pris la quête {quest:1472} de {npc:5675} au lieu de celle de {npc:5875}. Au niveau 20, {npc:5675}, dans le {object:36082}, vous envoie voir {npc:5693} dans le temple des Damnés, juste au nord.",
} end)()
t.guides["forever/class/warlock/orb-of-orahil"] = (function() return {
		["An off-hand orb or a staff for your late 30s, down the felhound's or the infernal's path, your pick."] = "Un orbe de main gauche ou un bâton vers la fin de la trentaine de niveaux, par la voie du gangrechien ou celle de l'infernal, au choix.",
		["At 35 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "Au niveau 35, {npc:3326}, dans la {object:172960}, vous envoie voir {npc:6266} à {area:392}.",
		["At 35 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "Au niveau 35, {npc:4563}, dans le {object:36082}, vous envoie voir {npc:6266} à {area:392}. Le zeppelin de {zone:1420} vole jusqu'à {zone:1411}.",
		["At 35 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "Au niveau 35, {npc:461}, dans l'{object:2164}, dans le {object:2101}, vous envoie voir {npc:6266} à {area:392}.",
		["At 35 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "Au niveau 35, {npc:5172}, à {zone:1455}, vous envoie voir {npc:6266} à {area:392}.",
		["Back to {npc:6266} in the tower above {area:392} with the cleansed orb. On the felhound path, wait while she completes the {item:15108}, then speak to her again."] = "Retournez voir {npc:6266} dans la tour au-dessus de {area:392} avec l'orbe purifié. Sur la voie du gangrechien, attendez qu'elle achève l'{item:15108}, puis parlez-lui à nouveau.",
		["Back to {npc:6266} in the tower above {area:392} with the spirit first: {npc:6546}'s cleansing follows it."] = "Retournez d'abord voir {npc:6266} dans la tour au-dessus de {area:392} avec l'esprit : la purification de {npc:6546} vient ensuite.",
		["Choose an acolyte"] = "Choisissez un acolyte",
		["On the infernal path, wait while {npc:6266} completes the {item:15107}, then speak to her again."] = "Sur la voie de l'infernal, attendez que {npc:6266} achève l'{item:15107}, puis parlez-lui à nouveau.",
		["Orb of Orahil"] = "Orbe d'Orahil",
		["Pick one acolyte: you can take only one of their quests. {npc:6254}'s felhound path ends with the Orb or {item:15106}, {npc:6252}'s infernal path with the Orb or {item:15105}. The guide follows the one you take."] = "Choisissez un acolyte : vous ne pouvez prendre qu'une de leurs quêtes. La voie du gangrechien de {npc:6254} se termine par l'Orbe ou le {item:15106}, la voie de l'infernal de {npc:6252} par l'Orbe ou le {item:15105}. Le guide suit celle que vous prenez.",
		["The demon's spirit"] = "L'esprit du démon",
		["The demons of {area:602}, in southern {zone:1443}, have all you need. Burning Blade Summoners carry the {item:7291}. On the felhound path, use the {item:12647} on a {npc:4678}, a felhound, and kill it for its spirit; on the infernal path, use the {item:12646} on a {npc:4676} and kill it."] = "Les démons du {area:602}, dans le sud de {zone:1443}, ont tout ce qu'il vous faut. Les Invocateurs de la Lame ardente portent l'{item:7291}. Sur la voie du gangrechien, utilisez le {item:12647} sur un {npc:4678}, un gangrechien, et tuez-le pour son esprit ; sur la voie de l'infernal, utilisez l'{item:12646} sur un {npc:4676} et tuez-le.",
		["The {item:15107}"] = "L'{item:15107}",
		["The {item:15108}"] = "L'{item:15108}",
		["Wait for the orb"] = "Attendez l'orbe",
		["{item:12648}, from a {npc:4678}"] = "{item:12648}, sur un {npc:4678}",
		["{item:12649}, from a {npc:4676}"] = "{item:12649}, sur un {npc:4676}",
		["{item:7291}, from the Burning Blade Summoners"] = "{item:7291}, sur les Invocateurs de la Lame ardente",
		["{npc:6252}: he gives you the {item:12646}"] = "{npc:6252} : il vous remet l'{item:12646}",
		["{npc:6254}: she gives you the {item:12647}"] = "{npc:6254} : elle vous remet le {item:12647}",
		["{npc:6266} and her two acolytes stand in the tower on the hill above {area:392}, beside {npc:6251}."] = "{npc:6266} et ses deux acolytes se tiennent dans la tour sur la colline au-dessus de {area:392}, à côté de {npc:6251}.",
		["{npc:6546} lives at her farm in western {zone:1445}. She calls the {npc:6549} out of the {item:7291}; it is elite: grouping up is advised."] = "{npc:6546} vit dans sa ferme, dans l'ouest du {zone:1445}. Elle fait sortir le {npc:6549} de l'{item:7291} ; il est élite : il est conseillé de former un groupe.",
} end)()
t.guides["forever/class/warlock/orb-of-soranruk"] = (function() return {
