t.guides["forever/class/warrior/voodoo-feathers"] = (function() return {
		["At 50, {npc:3041}, the warrior trainer of {zone:1456}, sends you to the {npc:7572} in the {zone:1435}."] = "Au niveau 50, {npc:3041}, le maître des guerriers de {zone:1456}, vous envoie voir le {npc:7572} dans le {zone:1435}.",
		["At 50, {npc:3354} in the {object:172958} sends you to the {npc:7572} in the {zone:1435}."] = "Au niveau 50, {npc:3354}, dans la {object:172958}, vous envoie voir le {npc:7572} dans le {zone:1435}.",
		["At 50, {npc:4593}, a warrior trainer of the {zone:1458}, sends you to the {npc:7572} in the {zone:1435}."] = "Au niveau 50, {npc:4593}, un maître des guerriers de {zone:1458}, vous envoie voir le {npc:7572} dans le {zone:1435}.",
		["At 50, {npc:5113}, the warrior trainer of {zone:1455}, sends you to the {npc:7572} in the {zone:1435}."] = "Au niveau 50, {npc:5113}, le maître des guerriers de {zone:1455}, vous envoie voir le {npc:7572} dans le {zone:1435}.",
		["At 50, {npc:5479} in {object:2100}, beside the Pig and Whistle, sends you to the {npc:7572} in the {zone:1435}."] = "Au niveau 50, {npc:5479}, dans la {object:2100}, à côté de la Taverne du Cochon siffleur, vous envoie voir le {npc:7572} dans le {zone:1435}.",
		["At 50, {npc:7315}, the warrior trainer of {zone:1457}, sends you to the {npc:7572} in the {zone:1435}."] = "Au niveau 50, {npc:7315}, le maître des guerriers de {zone:1457}, vous envoie voir le {npc:7572} dans le {zone:1435}.",
		["Back to the {npc:10996}"] = "Retour auprès du {npc:10996}",
		["Experience"] = "Expérience",
		["Experience at 50, ending in the {area:1417}; Forever removed the Classic item choice."] = "De l'expérience au niveau 50, avec une fin dans le {area:1417} ; Forever a supprimé le choix d'objet de Classic.",
		["Helboars"] = "Sangliers infernaux",
		["Shadowsworn camps"] = "Camps des liges d'ombre",
		["The Helboars roam the north of the {zone:1419}, south of the {npc:10996}."] = "Les Sangliers infernaux rôdent dans le nord des {zone:1419}, au sud du {npc:10996}.",
		["The Shadowsworn cultists hold the east of the {zone:1419}."] = "Les sectateurs lige d'ombre occupent l'est des {zone:1419}.",
		["The {area:1417}"] = "Le {area:1417}",
		["The {area:1417} lies under the {area:74} in the east of the {zone:1435}. Each of the six Atal'ai trolls on the balcony drops a voodoo feather: Gasher or {npc:5716} the amber, Hukku or Mijan the blue, Zolo or Loro the green. The {area:1417} is a dungeon and the trolls are elite: grouping up is advised."] = "Le {area:1417} se trouve sous le {area:74}, dans l'est du {zone:1435}. Chacun des six trolls atal'ai du balcon laisse tomber une plume vaudou : Balafreur ou {npc:5716} l'ambre, Hukku ou Mijan la bleue, Zolo ou Loro la verte. Le {area:1417} est un donjon et les trolls sont élites : il est conseillé de former un groupe.",
		["The {npc:7572}"] = "Le {npc:7572}",
		["The {npc:7572} stands in the south-west of the {zone:1435}, at the entrance to the {zone:1419}."] = "Le {npc:7572} se tient dans le sud-ouest du {zone:1435}, à l'entrée des {zone:1419}.",
} end)()
t.guides["forever/class/warrior/whirlwind-weapon"] = (function() return {
		["At 30, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Au niveau 30, {npc:3041}, le maître des guerriers des {zone:1456}, vous envoie voir {npc:6236} sur l'{area:720}, dans les {zone:1413}.",
		["At 30, {npc:3354} in the {object:172958} sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Au niveau 30, {npc:3354}, dans la {object:172958}, vous envoie voir {npc:6236} sur l'{area:720}, dans les {zone:1413}.",
		["At 30, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Au niveau 30, {npc:4595}, un maître des guerriers de {zone:1458}, vous envoie voir {npc:6236} sur l'{area:720}, dans les {zone:1413}.",
		["At 30, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Au niveau 30, {npc:5113}, le maître des guerriers de {zone:1455}, vous envoie voir {npc:6236} sur l'{area:720}, dans les {zone:1413}.",
		["At 30, {npc:5479} in {object:2100}, beside the Pig and Whistle, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Au niveau 30, {npc:5479}, dans la {object:2100} à côté de la taverne du Cochon siffleur, vous envoie voir {npc:6236} sur l'{area:720}, dans les {zone:1413}.",
		["Defeat the challengers and {npc:6238}"] = "Vainquez les adversaires et {npc:6238}",
		["Ride south along the coast from {area:392} to {area:720}. {npc:6236} stands by the arena: step on the grate to start the fight; the challengers come one at a time, then {npc:6238} (33)."] = "Longez la côte vers le sud de {area:392} jusqu'à l'{area:720}. {npc:6236} se tient près de l'arène : montez sur la grille pour lancer le combat ; les adversaires arrivent un par un, puis {npc:6238} (33).",
		["The Bloodscalp trolls hold the north-west of {zone:1434}; they drop the {item:3901}."] = "Les trolls Scalp-rouge occupent le nord-ouest de {zone:1434} ; ils laissent tomber la {item:3901}.",
		["The exiles of Arathi"] = "Les exilés d'Arathi",
		["Three kinds of elemental exiles roam {zone:1417}: Burning Exiles in the north-west, Thundering Exiles in the middle, Cresting Exiles in the north-east. Each drops its charm."] = "Trois sortes d'exilés élémentaires errent dans les {zone:1417} : les Exilés ardents au nord-ouest, les Exilés foudroyants au centre, les Exilés grimpeurs au nord-est. Chacun laisse tomber son charme.",
		["{item:3357}: {skill:182}, or the auction house"] = "{item:3357} : {skill:182}, ou l'hôtel des ventes",
		["{item:4479} from the Burning Exiles"] = "{item:4479} sur les Exilés ardents",
		["{item:4480} from the Thundering Exiles"] = "{item:4480} sur les Exilés foudroyants",
		["{item:4481} from the Cresting Exiles"] = "{item:4481} sur les Exilés grimpeurs",
		["{item:6894} from {quest:1712}"] = "{item:6894} sur {quest:1712}",
		["{npc:6176} camps in the south-east of {zone:1416}, above {zone:1424}; his cauldron stands beside him. He asks for a {item:3357}, a {item:3901} and the {quest:1714}, which his cauldron brews from three charms."] = "{npc:6176} campe au sud-est des {zone:1416}, au-dessus des {zone:1424} ; son chaudron est à côté de lui. Il demande une {item:3357}, une {item:3901} et l'{quest:1714}, que son chaudron prépare à partir de trois charmes.",
		["{quest:1712} waits just north of {npc:6176}'s camp and carries the {item:6894}. {quest:1712} is elite: grouping up is advised."] = "{quest:1712} attend juste au nord du camp de {npc:6176} et porte le {item:6894}. {quest:1712} est élite : un groupe est conseillé.",
		["{spell:2458} at 30 and a {spell:1680} axe, sword or warhammer at 40."] = "{spell:2458} au niveau 30, et une hache, une épée ou un marteau de guerre {spell:1680} au niveau 40.",
} end)()
t.guides["forever/collectibles/mounts/alliance/black-war-mounts"] = (function() return {
		["100g"] = "100 po",
		["Black War Mounts"] = "Montures de guerre noires",
		["Forever's PvP ranks come from {spell:1299382} earned in battlegrounds and world PvP, with a weekly cap; Commander (rank 11) unlocks the Black War mounts. Polestar cannot read your rank, so this step waits for level 40 and the riding skill."] = "Les rangs JcJ de Forever viennent des {spell:1299382} gagnés en champs de bataille et en JcJ sauvage, avec un plafond hebdomadaire ; Commandant (rang 11) débloque les montures de guerre noires. Polestar ne peut pas lire votre rang : cette étape attend donc le niveau 40 et la compétence de monte.",
		["PvP rank 11"] = "Rang JcJ 11",
		["{npc:12783} sells the mounts in the {area:2918} in {zone:1453}'s {object:2100}, beside the other honor quartermasters such as {npc:12805}. The Forever client lists each at 100g; choose one."] = "{npc:12783} vend les montures dans le {area:2918}, dans la {object:2100} de {zone:1453}, à côté des autres intendants d'honneur comme {npc:12805}. Le client Forever les affiche à 100 po chacune ; choisissez-en une.",
} end)()
t.guides["forever/collectibles/mounts/alliance/horse"] = (function() return {
