		["200g"] = "200 po",
		["Journeyman {skill:762}"] = "{skill:762} (compagnon)",
		["Skyboat from {area:279}"] = "Aéronef depuis {area:279}",
		["Skyboat from {zone:1456}"] = "Aéronef depuis {zone:1456}",
		["Skyboat to {zone:2521}"] = "Aéronef vers {zone:2521}",
