t.guides["forever/reputation/alterac-valley"] = (function() return {
		["Alterac Valley Reputation"] = "Réputation : Vallée d'Alterac",
		["Exalted with the {faction:729} earns a Legacy Point."] = "Être exalté auprès du {faction:729} rapporte un point d'héritage.",
		["Exalted with the {faction:730} earns a Legacy Point."] = "Être exalté auprès de la {faction:730} rapporte un point d'héritage.",
		["Full games that kill {npc:11946} after the towers fall pay the most."] = "Les parties complètes où {npc:11946} meurt après la chute des tours rapportent le plus.",
		["Full games that kill {npc:11948} after the towers fall pay the most."] = "Les parties complètes où {npc:11948} meurt après la chute des tours rapportent le plus.",
		["Keep winning {zone:1459}. More Booty! ({npc:13176}), {item:17306} for {npc:13236} (it summons {npc:13256}) and Alterac Ram Hides for the {npc:13441} all repeat."] = "Continuez à gagner {zone:1459}. Plus de butin ! ({npc:13176}), {item:17306} pour {npc:13236} (il invoque {npc:13256}) et les Peaux de bélier d'Alterac ({item:17642}) pour {npc:13441} se répètent tous.",
		["Keep winning {zone:1459}. More {quest:7223} ({npc:13257}), Storm Crystals for {npc:13442} (they summon {npc:13419}) and Frostwolf Hides for the {npc:13577} all repeat."] = "Continuez à gagner {zone:1459}. Encore des {quest:7223} ({npc:13257}), des Cristaux de tempête pour {npc:13442} (ils invoquent {npc:13419}) et des Peaux de loup des glaces pour le {npc:13577} : tout cela se répète.",
		["The {faction:729} holds {area:2978} in the south of {zone:1459}. Destroying towers, taking graveyards and mines, and killing captains and generals all pay reputation to the whole team. Loot {item:17422} from fallen enemies for {npc:13176}. Forever's Legacy Diplomat perk increases reputation gains."] = "Le {faction:729} tient {area:2978}, dans le sud de {zone:1459}. Détruire des tours, prendre des cimetières et des mines, et tuer capitaines et généraux rapportent de la réputation à toute l'équipe. Ramassez des {item:17422} sur les ennemis tombés pour {npc:13176}. L'atout Diplomate de l'Héritage de Forever augmente les gains de réputation.",
		["The {faction:730} holds {area:2959} in the north of {zone:1459}. Destroying towers, taking graveyards and mines, and killing captains and generals all pay reputation to the whole team. Loot {quest:7223} from fallen enemies for {npc:13257}. Forever's Legacy Diplomat perk increases reputation gains."] = "La {faction:730} tient {area:2959}, dans le nord de {zone:1459}. Détruire des tours, prendre des cimetières et des mines, et tuer capitaines et généraux rapportent de la réputation à toute l'équipe. Ramassez des {quest:7223} sur les ennemis tombés pour {npc:13257}. L'atout Diplomate de l'Héritage de Forever augmente les gains de réputation.",
		["{faction:729} to Exalted"] = "{faction:729} : Exalté",
		["{faction:729} to Friendly"] = "{faction:729} : Amical",
		["{faction:729} to Honored"] = "{faction:729} : Honoré",
		["{faction:729} to Revered"] = "{faction:729} : Révéré",
		["{faction:730} to Exalted"] = "{faction:730} : Exalté",
		["{faction:730} to Friendly"] = "{faction:730} : Amical",
		["{faction:730} to Honored"] = "{faction:730} : Honoré",
		["{faction:730} to Revered"] = "{faction:730} : Révéré",
		["{npc:12096}: Irondeep and {item:17542} from the mines"] = "{npc:12096} : Fournitures de Gouffrefer et de Froide-dent ({item:17542}) des mines",
		["{npc:12097}: Coldtooth and {item:17522} from the mines"] = "{npc:12097} : Fournitures de Froide-dent et de Gouffrefer ({item:17522}) des mines",
		["{npc:13176}: More Booty!"] = "{npc:13176} : Plus de butin !",
		["{npc:13236}: A Gallon of Blood"] = "{npc:13236} : Quelques litres de sang",
		["{npc:13257}: More {quest:7223}"] = "{npc:13257} : encore des {quest:7223}",
		["{npc:13442}: Crystal Cluster"] = "{npc:13442} : Grappes de cristaux",
} end)()
t.guides["forever/reputation/arathi-basin"] = (function() return {
		["Arathi Basin Reputation"] = "Réputation : Bassin Arathi",
		["Exalted with the League of Arathor earns a Legacy Point."] = "Être exalté auprès de La Ligue d'Arathor rapporte un point d'héritage.",
		["Exalted with {faction:510} earns a Legacy Point."] = "Être exalté auprès de {faction:510} rapporte un point d'héritage.",
		["Keep playing {zone:1461}. On Call to Arms: {zone:1461} weekends the {npc:15350} in the capitals takes three Arathi Basin Marks of Honor for extra reputation."] = "Continuez à jouer au {zone:1461}. Pendant les week-ends de l'Appel aux armes du {zone:1461}, {npc:15350} des capitales prend trois Marques d'honneur du bassin d'Arathi contre un supplément de réputation.",
		["Keep playing {zone:1461}. On Call to Arms: {zone:1461} weekends the {npc:15351} in the capitals takes three Arathi Basin Marks of Honor for extra reputation."] = "Continuez à jouer au {zone:1461}. Pendant les week-ends de l'Appel aux armes du {zone:1461}, {npc:15351} des capitales prend trois Marques d'honneur du bassin d'Arathi contre un supplément de réputation.",
		["Keep playing {zone:1461}; wins with many bases held pay the most."] = "Continuez à jouer {zone:1461} ; les victoires avec beaucoup de bases tenues rapportent le plus.",
		["League of Arathor to Exalted"] = "La Ligue d'Arathor : Exalté",
		["League of Arathor to Friendly"] = "La Ligue d'Arathor : Amical",
		["League of Arathor to Honored"] = "La Ligue d'Arathor : Honoré",
		["League of Arathor to Revered"] = "La Ligue d'Arathor : Révéré",
		["{faction:509} fights for {zone:1461} from {area:320}. Their reputation comes from the battleground: the resources your team gathers pay it to everyone, so holding more bases for longer pays more. Queue at any battlemaster. Forever's Legacy Diplomat perk increases reputation gains."] = "{faction:509} se bat pour {zone:1461} depuis {area:320}. Sa réputation vient du champ de bataille : les ressources que votre équipe accumule la rapportent à tous, donc tenir plus de bases plus longtemps rapporte plus. Inscrivez-vous auprès de n'importe quel maître de guerre. L'atout Diplomate de l'Héritage de Forever augmente les gains de réputation.",
		["{faction:510} fight for {zone:1461} from {area:321}. Their reputation comes from the battleground: the resources your team gathers pay it to everyone, so holding more bases for longer pays more. Queue at any battlemaster. Forever's Legacy Diplomat perk increases reputation gains."] = "{faction:510} se battent pour {zone:1461} depuis {area:321}. Leur réputation vient du champ de bataille : les ressources que votre équipe accumule la rapportent à tous, donc tenir plus de bases plus longtemps rapporte plus. Inscrivez-vous auprès de n'importe quel maître de guerre. L'atout Diplomate de l'Héritage de Forever augmente les gains de réputation.",
		["{faction:510} to Exalted"] = "{faction:510} : Exalté",
		["{faction:510} to Friendly"] = "{faction:510} : Amical",
		["{faction:510} to Honored"] = "{faction:510} : Honoré",
		["{faction:510} to Revered"] = "{faction:510} : Révéré",
		["{npc:14983}'s The Battle for {zone:1461}! (assault every base) and Control Four Bases / Control Five Bases are one-time quests; {npc:14984} beside him takes Arathi Resource Crates."] = "La bataille pour {zone:1461} ! de {npc:14983} (attaquer chaque base) et Contrôler quatre bases / Prendre cinq bases sont des quêtes uniques ; {npc:14984}, à côté de lui, prend les Caisses de ressources d'Arathi.",
		["{npc:15021}'s The Battle for {zone:1461}! (assault every base) and Take Four Bases / Take Five Bases are one-time quests; {npc:15022} beside him takes Arathi Resource Crates."] = "La bataille pour {zone:1461} ! de {npc:15021} (attaquer chaque base) et Prendre quatre bases / Prendre cinq bases sont des quêtes uniques ; {npc:15022}, à côté de lui, prend les Caisses de ressources d'Arathi.",
		["{npc:15126} hands out one Defiler's care package by level"] = "{npc:15126} remet un colis des Profanateurs par tranche de niveau",
		["{npc:15127} hands out one Arathor care package by level"] = "{npc:15127} remet un colis d'Arathor par tranche de niveau",
} end)()
t.guides["forever/reputation/argent-dawn"] = (function() return {
		["Argent Dawn Reputation"] = "Réputation : Aube d'argent",
		["Corruptor's Scourgestones and dungeons to Revered"] = "Pierres du Fléau des corrupteurs et donjons jusqu'à Révéré",
		["Dark Adepts and Shadowmages (level 58-60) drop Invader's Scourgestones here, along with Minion's stones and {item:14047}. Hand Invader's in 10 at a time and Minion's 20 at a time to {npc:11039} at {area:2268}. In Classic both stop giving reputation at Honored."] = "Les Adeptes noirs et les Ombremages (niveau 58-60) laissent tomber ici des Pierres du Fléau des envahisseurs, ainsi que des pierres des serviteurs et de l'{item:14047}. Rendez celles des envahisseurs par 10 et celles des serviteurs par 20 à {npc:11039} à {area:2268}. En Classic, les deux ne rapportent plus de réputation à partir d'Honoré.",
		["From Honored on, Corruptor's Scourgestones (one per turn-in) and Scourge kills in {area:2279} and {area:2057} carry the reputation. Corruptor's stones drop from the Scourge bosses there ({npc:1853}, {npc:10433}, Vectus) and from {npc:1852} and Putridius in {zone:1422}. Many dungeon runs pay off faster than any open-world farm."] = "À partir d'Honoré, les Pierres du Fléau des corrupteurs (une par remise) et les morts du Fléau à {area:2279} et à {area:2057} apportent la réputation. Les pierres des corrupteurs tombent des boss du Fléau de ces donjons ({npc:1853}, {npc:10433}, Vectus) ainsi que de {npc:1852} et Putridius dans {zone:1422}. Enchaîner les donjons rapporte plus vite que tout farm en extérieur.",
		["Ghouls and skeletons all over {zone:1422} drop Minion's Scourgestones about half the time; this cluster is dense. Hand them in 20 at a time to any Argent Officer (Pureheart at {area:3197}, Garush at {area:813}, {npc:11039} at {area:2268}). Each turn-in also pays an {item:12844} for the Argent quartermasters."] = "Les goules et squelettes de tout {zone:1422} laissent tomber des Pierres du Fléau des serviteurs environ une fois sur deux ; ce secteur est dense. Rendez-les par 20 à n'importe quel officier de l'Aube d'argent (Pureheart à {area:3197}, Garush à {area:813}, {npc:11039} à {area:2268}). Chaque remise rapporte aussi une {item:12844} pour les intendants de l'Aube d'argent.",
		["Invader's Scourgestones to Honored"] = "Pierres du Fléau des envahisseurs jusqu'à Honoré",
		["Keep running {area:2279} and {area:2057} and turning in every {item:12843} at {area:2268} until Exalted."] = "Continuez {area:2279} et {area:2057} et rendez chaque {item:12843} à {area:2268} jusqu'à Exalté.",
		["Minion's Scourgestones to Friendly"] = "Pierres du Fléau des serviteurs jusqu'à Amical",
		["Run {area:2279} (both wings) and {area:2057}, killing every Scourge you pass."] = "Faites {area:2279} (les deux ailes) et {area:2057} en tuant tous les membres du Fléau croisés.",
		["{faction:529} to Exalted"] = "{faction:529} jusqu'à Exalté",
		["{object:2160} starts out Neutral. Take the Commission from {npc:10839} at {area:813} and wear it: in Classic, Scourgestones only drop while the {quest:5401} trinket is equipped. Forever's Legacy Diplomat perk increases reputation gains."] = "{object:2160} commence au niveau Neutre. Prenez le brevet auprès de {npc:10839} à {area:813} et portez-le : en Classic, les Pierres du Fléau ne tombent que si le bijou {quest:5401} est équipé. L'atout Diplomate de l'Héritage de Forever augmente les gains de réputation.",
		["{object:2160} starts out Neutral. Take the Commission from {npc:10840} at {area:3197} and wear it: in Classic, Scourgestones only drop while the {quest:5401} trinket is equipped. Forever's Legacy Diplomat perk increases reputation gains."] = "{object:2160} commence au niveau Neutre. Prenez le brevet auprès de {npc:10840} à {area:3197} et portez-le : en Classic, les Pierres du Fléau ne tombent que si le bijou {quest:5401} est équipé. L'atout Diplomate de l'Héritage de Forever augmente les gains de réputation.",
		["{quest:5401} (Alliance)"] = "{quest:5401} (Alliance)",
		["{quest:5401} (Horde)"] = "{quest:5401} (Horde)",
} end)()
t.guides["forever/reputation/cenarion-circle"] = (function() return {
		["Abyssal Crests, Abyssal Signets and Abyssal Scepters are repeatable at {npc:15306} once their opening quests are done."] = "Les blasons abyssaux, Les chevalières abyssales et Les sceptres abyssaux se répètent auprès de {npc:15306} une fois leurs quêtes d'ouverture terminées.",
		["Back to {area:3425}"] = "Retour à {area:3425}",
		["Cenarion Circle Reputation"] = "Réputation : Cercle cénarien",
		["Encrypted Twilight Texts repeats: {npc:15306} takes more texts again and again. The cultist camps are the place to farm them."] = "Les textes du crépuscule cryptés se répète : {npc:15306} reprend des textes encore et encore. Les camps de sectateurs sont l'endroit où les farmer.",
		["Encrypted Twilight Texts to Friendly"] = "Les textes du crépuscule cryptés jusqu'à Amical",
		["From here on, the {area:3454} raid and the Abyssal Council turn-ins (crests, signets, scepters) carry most of the reputation."] = "À partir d'ici, le raid {area:3454} et les remises du Conseil abyssal (blasons, chevalières, sceptres) apportent l'essentiel de la réputation.",
		["Keep farming the Twilight camps. Wearing the Twilight Trappings (the Twilight cultist set plus a Medallion of Station, from {npc:15282}'s Medallion of Station quest) lets you summon Abyssal Templars at the Wind Stones; their Abyssal Crests go to {npc:15306}."] = "Continuez à farmer les camps du crépuscule. Porter la tenue du crépuscule (l'ensemble de sectateur du crépuscule plus un Médaillon de statut de sectateur du crépuscule, de la quête Le médaillon de statut de {npc:15282}) permet d'invoquer des Templiers abyssaux aux Pierres des vents ; leurs Blasons abyssaux vont à {npc:15306}.",
		["Keep running the {area:3454} and turning in Abyssal Council insignia until Exalted."] = "Continuez les {area:3454} et les remises d'insignes du Conseil abyssal jusqu'à Exalté.",
		["Twilight's Hammer cultists hold the camps in western {zone:1451}. {quest:8320} and Stonecallers mix here; any cultist can drop an {item:20404}. Every cultist kill also counts toward the {faction:609}. The Geolords count for {quest:8320} only if you are 60 and took it."] = "Les sectateurs du Marteau du crépuscule tiennent les camps de l'ouest de {zone:1451}. {quest:8320} et Invocateurs des pierres s'y mêlent ; tout sectateur peut laisser un {item:20404}. Chaque sectateur tué compte aussi pour le {faction:609}. Les Géoseigneurs ne comptent pour {quest:8320} que si vous êtes niveau 60 et avez pris la quête.",
		["{area:3425} is the walled town in north-central {zone:1451}. Bor and {npc:15270} stand together inside. The {faction:609} starts out Neutral. Forever's Legacy Diplomat perk increases reputation gains."] = "{area:3425} est la ville fortifiée au centre-nord de {zone:1451}. Bor et {npc:15270} se tiennent ensemble à l'intérieur. Le {faction:609} commence à Neutre. L'atout Diplomate de l'Héritage de Forever augmente les gains de réputation.",
		["{faction:609} to Exalted"] = "{faction:609} jusqu'à Exalté",
		["{faction:609} to Honored"] = "{faction:609} jusqu'à Honoré",
		["{faction:609} to Revered"] = "{faction:609} jusqu'à Révéré",
		["{npc:15306}: Encrypted Twilight Texts"] = "{npc:15306} : Les textes du crépuscule cryptés",
		["{quest:8320} needs level 60"] = "{quest:8320} demande le niveau 60",
} end)()
t.guides["forever/reputation/darkspear-trolls"] = (function() return {
		["Dark Adepts and Shadowmages (level 58-60) drop it here; every Scourge kill here also counts toward the {object:92525} (see that guide). The Auction House works too."] = "Les Adeptes noirs et Ombremages (niveau 58-60) en lâchent ici ; chaque Fléau tué ici compte aussi pour l'{object:92525} (voir ce guide). L'hôtel des ventes fonctionne aussi.",
		["Darkspear Trolls Reputation"] = "Réputation : Trolls Darkspear",
		["Dunemaul ogres (level 45-48) drop it here. The Auction House works too."] = "Les ogres Cognedune (niveau 45-48) en lâchent ici. L'hôtel des ventes fonctionne aussi.",
		["Keep handing in {quest:7837} until {faction:530} is Exalted. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "Continuez à rendre {quest:7837} jusqu'à être Exalté auprès de {faction:530}. {item:14047} : Adeptes noirs et Ombremages (niveau 58-60) dans les {zone:1423}, ou l'hôtel des ventes.",
		["Keep handing in {quest:7837}, 20 {item:14047} at a time. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "Continuez à rendre {quest:7837}, 20 {item:14047} à la fois. {item:14047} : Adeptes noirs et Ombremages (niveau 58-60) dans les {zone:1423}, ou l'hôtel des ventes.",
		["Kolkar centaur (level 30-33) drop it here. The Auction House works too."] = "Les centaures kolkar (niveau 30-33) en lâchent ici. L'hôtel des ventes fonctionne aussi.",
		["Venture Co. Enforcers at the {area:381} (level 16-17) drop it here. The Auction House works too."] = "Les Massacreurs de la KapitalRisk de la {area:381} (niveau 16-17) en lâchent ici. L'hôtel des ventes fonctionne aussi.",
		["{npc:14727} takes cloth for {faction:530} in the {object:172961}, {zone:1454}. The first donations of Wool, Silk, Mageweave and {item:14047} (60 cloth each) are done once and give the most reputation per cloth; after them, {quest:7837} repeats until Exalted. Exalted with another race's city lets you buy that race's mounts. Forever's Legacy Diplomat perk increases reputation gains."] = "{npc:14727} prend les étoffes pour {faction:530} dans la {object:172961}, à {zone:1454}. Les premiers dons d'étoffe de laine, de soie, de tisse-mage et d'{item:14047} (60 étoffes chacun) se font une fois et donnent le plus de réputation par étoffe ; ensuite, {quest:7837} se répète jusqu'à Exalté. Être Exalté auprès de la ville d'une autre race permet d'acheter les montures de cette race. L'atout Diplomate de l'Héritage de Forever augmente les gains de réputation.",
		["{npc:14727}: {item:14047} delivered"] = "{npc:14727} : {item:14047} livrée",
		["{quest:7837} takes 20 {item:14047} per turn-in and repeats as often as you like. Bring {item:14047} in multiples of 20 and hand them all in at once, one turn-in after another. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "{quest:7837} prend 20 {item:14047} par remise et se répète à volonté. Apportez l'{item:14047} par multiples de 20 et rendez tout d'un coup, une remise après l'autre. {item:14047} : Adeptes noirs et Ombremages (niveau 58-60) dans les {zone:1423}, ou l'hôtel des ventes.",
		["{quest:7837} to Exalted"] = "{quest:7837} jusqu'à Exalté",
		["{quest:7837} to Honored"] = "{quest:7837} jusqu'à Honoré",
		["{quest:7837} to Revered"] = "{quest:7837} jusqu'à Révéré",
} end)()
t.guides["forever/reputation/darnassus"] = (function() return {
		["Dark Adepts and Shadowmages (level 58-60) drop it here; every Scourge kill here also counts toward the {object:92525} (see that guide). The Auction House works too."] = "Les Adeptes noirs et les Ombremages (niveau 58-60) en lâchent ici ; chaque Fléau tué ici compte aussi pour {object:92525} (voir ce guide). L'hôtel des ventes convient aussi.",
		["Darnassus Reputation"] = "Réputation : Darnassus",
