t.guides["forever/reputation/thorium-brotherhood"] = (function() return {
		["Back to Burninate"] = "Retour auprès de Burninate",
		["Keep turning in {area:2717} materials and {item:11099} at Lokhtos until Exalted."] = "Continuez à rendre des matériaux de {area:2717} et du {item:11099} auprès de Lokhtos jusqu'à Exalté.",
		["Restoring Fiery Flux Supplies repeats in three versions: {item:3356}, Iron Bars or {item:4234}, each with Coal and an {item:18944}. Incendosaurs (level 47-49) in the north of {zone:1427} drop a scale every time; Burninate himself sells Coal."] = "Réapprovisionnement en flux embrasé se répète en trois versions : {item:3356}, Barres de fer ({item:3575}) ou {item:4234}, chacune avec du Charbon et une {item:18944}. Les Incendosaures (niveau 47-49) du nord de la {zone:1427} lâchent une écaille à chaque fois ; Burninate lui-même vend le Charbon.",
		["The plans lie in the {area:1443} of the Cauldron, guarded by {object:147516} dwarves. {object:147516} dwarves also drop {item:18945}, which Burninate takes for Gaining Acceptance."] = "Les plans se trouvent dans {area:1443} du Chaudron, gardés par des nains {object:147516}. Les nains {object:147516} lâchent aussi {item:18945}, que Burninate prend pour Se faire accepter.",
		["The {area:2717} materials carry the rest: Fiery Cores drop from Firewalkers, Flameguards and Firelords, and Lava Cores from Lava Elementals, Lava Reavers and Molten Destroyers there. {item:11382} comes from Molten Destroyers and rarely elsewhere."] = "Les matériaux de {area:2717} font le reste : les Noyaux de feu tombent sur les Marchefeux, Gardes des flammes et Seigneurs du feu, et les Noyaux de lave sur les Élémentaires de lave, Ravageurs de lave et Destructeurs de lave sur place. {item:11382} vient des Destructeurs de lave et rarement d'ailleurs.",
		["Thorium Brotherhood Reputation"] = "Réputation : Confrérie du thorium",
		["{area:1446}, on the scaffolds in the north-west of {zone:1427}, is the Brotherhood's outpost. The {faction:59} starts out Neutral. Forever's Legacy Diplomat perk increases reputation gains."] = "{area:1446}, sur les échafaudages au nord-ouest de {zone:1427}, est l'avant-poste de la Confrérie. Votre réputation auprès de {faction:59} commence à Neutre. L'atout Diplomate de l'Héritage de Forever augmente les gains de réputation.",
		["{area:2717} materials: Favor Amongst the Brotherhood, {item:17010}, {item:17011}, {item:17012} and {item:11382}, all repeatable at Lokhtos."] = "Matériaux de {area:2717} : Faveur auprès de la Confrérie, {item:17010}, {item:17011}, {item:17012} et {item:11382}, toutes répétables auprès de Lokhtos.",
		["{faction:59} to Exalted"] = "{faction:59} jusqu'à Exalté",
		["{faction:59} to Revered"] = "{faction:59} jusqu'à Révéré",
		["{item:11099}: Favor Amongst the Brotherhood, {item:11099} at Lokhtos, repeatable."] = "{item:11099} : Faveur auprès de la Confrérie, {item:11099}, auprès de Lokhtos, répétable.",
		["{item:18942} supplies to Friendly"] = "Réserves de {item:18942} jusqu'à Amical",
		["{npc:12944} to Honored"] = "{npc:12944} jusqu'à Honoré",
		["{npc:12944} trades in the Grim Guzzler inside {area:1584}. His Favor Amongst the Brotherhood turn-ins take {item:11099} (mined from Dark Iron Deposits with {skill:186}), {item:11382}, {item:17010}, {item:17011} and {item:17012}. {npc:14387} at the {area:1445} entrance offers attunement to the {area:2717}."] = "{npc:12944} commerce au Sinistre dévoreur, dans les {area:1584}. Ses remises Faveur auprès de la Confrérie prennent du {item:11099} (extrait des Gisements de sombrefer ({object:165658}) avec {skill:186}), du {item:11382}, des {item:17010}, des {item:17011} et du {item:17012}. {npc:14387}, à l'entrée du {area:1445}, propose l'harmonisation au {area:2717}.",
		["{npc:14624}: Restoring Fiery Flux Supplies"] = "{npc:14624} : Réapprovisionnement en flux embrasé",
} end)()
t.guides["forever/reputation/thunder-bluff"] = (function() return {
		["Dark Adepts and Shadowmages (level 58-60) drop it here; every Scourge kill here also counts toward the {object:92525} (see that guide). The Auction House works too."] = "Les Adeptes noirs et les Ombremages (niveau 58-60) en laissent tomber ici ; chaque Fléau tué ici compte aussi pour {object:92525} (voir ce guide). L'Hôtel des ventes convient aussi.",
		["Dunemaul ogres (level 45-48) drop it here. The Auction House works too."] = "Les Ogres Cognedune (niveau 45-48) en laissent tomber ici. L'Hôtel des ventes convient aussi.",
		["Keep handing in {quest:7825} until {faction:81} is Exalted. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "Continuez à rendre {quest:7825} jusqu'à être Exalté auprès de {faction:81}. {item:14047} : Adeptes noirs et Ombremages (niveau 58-60) dans les {zone:1423}, ou l'Hôtel des ventes.",
		["Keep handing in {quest:7825}, 20 {item:14047} at a time. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "Continuez à rendre {quest:7825}, 20 {item:14047} à la fois. {item:14047} : Adeptes noirs et Ombremages (niveau 58-60) dans les {zone:1423}, ou l'Hôtel des ventes.",
		["Kolkar centaur (level 30-33) drop it here. The Auction House works too."] = "Les Centaures kolkar (niveau 30-33) en laissent tomber ici. L'Hôtel des ventes convient aussi.",
		["Thunder Bluff Reputation"] = "Réputation : Thunder Bluff",
		["Venture Co. Enforcers at the {area:381} (level 16-17) drop it here. The Auction House works too."] = "Les Massacreurs de la KapitalRisk de la {area:381} (niveau 16-17) en laissent tomber ici. L'Hôtel des ventes convient aussi.",
		["{npc:14728} takes cloth for {faction:81} in {faction:81}. The first donations of Wool, Silk, Mageweave and {item:14047} (60 cloth each) are done once and give the most reputation per cloth; after them, {quest:7825} repeats until Exalted. Exalted with another race's city lets you buy that race's mounts. Forever's Legacy Diplomat perk increases reputation gains."] = "{npc:14728} accepte le tissu pour {faction:81}, à {faction:81}. Les premiers dons de laine, de soie, de tisse-mage et de {item:14047} (60 tissus chacun) ne se font qu'une fois et rapportent le plus de réputation par tissu ; ensuite, {quest:7825} se répète jusqu'à Exalté. Être Exalté auprès de la ville d'une autre race permet d'acheter les montures de cette race. L'atout Diplomate de l'Héritage de Forever augmente les gains de réputation.",
		["{npc:14728}: {item:14047} delivered"] = "{npc:14728} : {item:14047} livré",
		["{quest:7825} takes 20 {item:14047} per turn-in and repeats as often as you like. Bring {item:14047} in multiples of 20 and hand them all in at once, one turn-in after another. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "{quest:7825} demande 20 {item:14047} par rendu et se répète autant que vous voulez. Apportez du {item:14047} par multiples de 20 et rendez tout d'un coup, un rendu après l'autre. {item:14047} : Adeptes noirs et Ombremages (niveau 58-60) dans les {zone:1423}, ou l'Hôtel des ventes.",
		["{quest:7825} to Exalted"] = "{quest:7825} jusqu'à Exalté",
		["{quest:7825} to Honored"] = "{quest:7825} jusqu'à Honoré",
		["{quest:7825} to Revered"] = "{quest:7825} jusqu'à Révéré",
} end)()
t.guides["forever/reputation/timbermaw-hold"] = (function() return {
		["Alternate Deadwood feathers ({npc:15395}) and Winterfall beads ({npc:11556}), whichever camp is less crowded."] = "Alternez plumes Mort-bois ({npc:15395}) et perles Tombe-hiver ({npc:11556}), selon le camp le moins fréquenté.",
		["Back to {npc:11554}"] = "Retour à {npc:11554}",
		["Back to {npc:11556}"] = "Retour à {npc:11556}",
		["Back to {npc:15395}"] = "Retour à {npc:15395}",
		["Deadwood furbolgs (level 48-50) camp at the southern end of {zone:1448}. Keep every {item:21377} they drop: {npc:11554} and {npc:15395} take them later."] = "Les furbolgs Mort-bois (niveau 48-50) campent à l'extrémité sud de {zone:1448}. Gardez chaque {item:21377} qu'ils lâchent : {npc:11554} et {npc:15395} les prennent plus tard.",
		["Feathers and beads to Friendly"] = "Plumes et perles jusqu'à Amical",
		["Feathers for {npc:11554} and Feathers for {npc:15395} (Deadwood Headdress Feathers) and Beads for {npc:11556} ({item:21383}) repeat as often as you like; every Deadwood or Winterfall kill counts as well. {area:2244} is the densest bead spot."] = "Des plumes pour {npc:11554} et Des plumes pour {npc:15395} (Coiffures de plumes mort-bois) et Des perles pour {npc:11556} ({item:21383}) se répètent à volonté ; chaque Mort-bois ou Tombe-hiver tué compte aussi. Le {area:2244} est le meilleur endroit pour les perles.",
		["Feathers to Honored"] = "Plumes jusqu'à Honoré",
		["Go through {faction:576} to its {zone:1452} exit; {npc:11556} stands just outside. The quests and kills so far usually reach Unfriendly, and then the Timbermaw let you pass. If they still show red, kill more Deadwood by the tunnel first."] = "Traversez le territoire de {faction:576} jusqu'à la sortie de {zone:1452} ; {npc:11556} se tient juste dehors. Les quêtes et victimes jusqu'ici suffisent en général pour Inamical, et les Grumegueules vous laissent alors passer. S'ils apparaissent encore en rouge, tuez d'abord d'autres Mort-bois près du tunnel.",
		["Keep turning in feathers and beads until Exalted."] = "Continuez à rendre plumes et perles jusqu'à Exalté.",
		["The northern Deadwood (level 53-55) hold the camps just south of the tunnel. Keep their feathers too."] = "Les Mort-bois du nord (niveau 53-55) tiennent les camps juste au sud du tunnel. Gardez aussi leurs plumes.",
		["The northern Deadwood camps by the tunnel are the densest feather spot (35% drop chance there). Hand feathers to {npc:15395} at the tunnel, or to {npc:11554} in the south."] = "Les camps Mort-bois du nord près du tunnel sont le meilleur endroit pour les plumes (35 % de chances de butin). Donnez les plumes à {npc:15395} au tunnel, ou à {npc:11554} au sud.",
		["Timbermaw Hold Reputation"] = "Réputation : Les Grumegueules",
		["{area:2244} sits on the eastern side of {zone:1452}. Keep every {item:21383} you loot: {npc:11556} takes them."] = "Le {area:2244} est à l'est de {zone:1452}. Gardez chaque {item:21383} ramassée : {npc:11556} les prend.",
		["{faction:576} starts out Hostile, and its furbolgs in the tunnels attack until you reach Unfriendly. Every Deadwood and Winterfall furbolg you kill raises it, so the quests below pay twice. Forever's Legacy Diplomat perk increases reputation gains."] = "{faction:576} commence Hostile, et ses furbolgs des tunnels attaquent jusqu'à ce que vous soyez Inamical. Chaque furbolg Mort-bois ou Tombe-hiver tué l'augmente : les quêtes ci-dessous rapportent donc deux fois. L'atout Diplomate de l'Héritage de Forever augmente les gains de réputation.",
		["{faction:576} to Exalted"] = "{faction:576} jusqu'à Exalté",
		["{faction:576} to Revered"] = "{faction:576} jusqu'à Révéré",
		["{npc:11556}: Beads for {npc:11556}"] = "{npc:11556} : Des perles pour {npc:11556}",
		["{npc:15395} waits in northern {zone:1448} at the tunnel into {faction:576}."] = "{npc:15395} attend au nord de {zone:1448}, au tunnel menant chez {faction:576}.",
		["{npc:15395}: Feathers for {npc:15395}"] = "{npc:15395} : Des plumes pour {npc:15395}",
} end)()
t.guides["forever/reputation/undercity"] = (function() return {
